-- Rift: every migration, in order, safe to run on the production database
-- whatever it already has. Generated by scripts/pending-migrations.mjs from
-- 44 files, the last 20260928000000_rift_step_marks.
--
-- Supabase dashboard > SQL Editor > New query > paste all of this > Run.
-- Running it twice is safe: a part the database already has is skipped.


-- =====================================================================
-- 20260907000000_rift_core.sql
-- =====================================================================
-- ============================================================================
-- Rift core schema: phase 1
--
-- Additive. The retired portal MVP's tables (clients, roadmaps, dpa_programs,
-- agents_settings) are applied to this project and are left alone; Rift's
-- tables live alongside them under the rift_ prefix until the old ones can be
-- dropped. Nothing here reads or writes them.
--
-- Everything in docs/schema.md that is load-bearing is enforced here rather
-- than in application code, because each of these fails as a WRONG NUMBER in
-- front of a person rather than as an error:
--
--   * a custom funnel question can never feed a calculation
--   * first touch is written once and never updated
--   * a figure cannot be "verified" without a named party
--   * a telemetry event can never carry an answer value
--
-- Every table gets its RLS policy in this same migration. A table shipped
-- without one is either wide open or unreadable, and both are found in
-- production.
-- ============================================================================

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------------------
-- Identity and configuration
-- ---------------------------------------------------------------------------

create table if not exists rift_agents (
  id            uuid primary key default gen_random_uuid(),
  auth_user_id  uuid unique references auth.users(id) on delete cascade,
  name          text not null,
  brokerage     text,
  license       text,
  email         text not null,
  phone         text,
  service_area  text[] not null default '{}',
  created_at    timestamptz not null default now()
);

-- The six decisions that are the business owner's, not engineering's.
-- `decided_at` is null while a rule is still on its default: a rule somebody
-- chose and a rule nobody has looked at must be distinguishable.
create table if not exists rift_business_rules (
  agent_id    uuid not null references rift_agents(id) on delete cascade,
  key         text not null,
  value       jsonb not null,
  decided_at  timestamptz,
  decided_by  text,
  updated_at  timestamptz not null default now(),
  primary key (agent_id, key)
);

-- ---------------------------------------------------------------------------
-- The funnel
-- ---------------------------------------------------------------------------

create table if not exists rift_funnels (
  id          uuid primary key default gen_random_uuid(),
  agent_id    uuid not null references rift_agents(id) on delete cascade,
  side        text not null check (side in ('buy','sell')),
  version     integer not null default 1,
  created_at  timestamptz not null default now(),
  unique (agent_id, side)
);

-- Published versions are immutable. Editing produces a new row, never an
-- update, because a lead is pinned to the version it actually answered and a
-- retroactive edit would rewrite what a person was asked.
create table if not exists rift_funnel_versions (
  id           uuid primary key default gen_random_uuid(),
  funnel_id    uuid not null references rift_funnels(id) on delete cascade,
  version      integer not null,
  published_at timestamptz not null default now(),
  changed_by   text,
  change_note  text,
  unique (funnel_id, version)
);

create table if not exists rift_questions (
  id                 uuid primary key default gen_random_uuid(),
  funnel_version_id  uuid not null references rift_funnel_versions(id) on delete cascade,
  key                text not null,
  kind               text not null check (kind in ('core','custom')),
  -- The compute input this question feeds. Core questions name one; custom
  -- questions must not, and the constraint below is why an agent can invent
  -- questions without being able to break anybody's numbers.
  bound              text,
  type               text not null check (type in ('choice','number','slider','text','money')),
  title              text not null,
  description        text,
  field_label        text,
  unit               text,
  options            jsonb not null default '[]'::jsonb,
  required           boolean not null default false,
  enabled            boolean not null default true,
  sort_order         integer not null default 0,
  unique (funnel_version_id, key),
  constraint custom_questions_are_inert check (kind = 'core' or bound is null),
  constraint core_questions_are_bound  check (kind = 'custom' or bound is not null)
);

-- ---------------------------------------------------------------------------
-- Assessment and capture
-- ---------------------------------------------------------------------------

create table if not exists rift_assessments (
  id                 uuid primary key default gen_random_uuid(),
  agent_id           uuid not null references rift_agents(id) on delete cascade,
  session_id         text not null,
  side               text not null check (side in ('buy','sell')),
  funnel_version_id  uuid references rift_funnel_versions(id) on delete set null,
  started_at         timestamptz not null default now(),
  completed_at       timestamptz,
  -- Abandoned assessments are most of the value here, so they are first-class
  -- rows rather than rows we forgot to delete.
  abandoned_at       timestamptz,
  county             text,
  created_at         timestamptz not null default now()
);
create index if not exists rift_assessments_agent_idx   on rift_assessments (agent_id, started_at desc);
create index if not exists rift_assessments_session_idx on rift_assessments (session_id);

create table if not exists rift_answers (
  id             uuid primary key default gen_random_uuid(),
  assessment_id  uuid not null references rift_assessments(id) on delete cascade,
  question_key   text not null,
  value          jsonb not null,
  answered_at    timestamptz not null default now(),
  unique (assessment_id, question_key)
);

-- Telemetry lives apart from answers, permanently, with its own retention.
-- The moment one query can join an event to the value that was typed, funnel
-- analytics becomes a dossier, so the payload is forbidden from carrying one.
create table if not exists rift_events (
  id             bigserial primary key,
  agent_id       uuid not null references rift_agents(id) on delete cascade,
  session_id     text not null,
  name           text not null,
  side           text check (side in ('buy','sell')),
  question_key   text,
  dwell_ms       integer,
  payload        jsonb not null default '{}'::jsonb,
  at             timestamptz not null default now(),
  constraint events_carry_no_answer check (
    not (payload ? 'value' or payload ? 'answer' or payload ? 'input')
  )
);
create index if not exists rift_events_agent_idx    on rift_events (agent_id, at desc);
create index if not exists rift_events_session_idx  on rift_events (session_id);
create index if not exists rift_events_question_idx on rift_events (question_key, name);

-- First touch never moves. Enforced by trigger rather than by application
-- code: an agent who re-attributes a referral to the retargeting ad that
-- caught it on the way back will keep buying retargeting and stop asking for
-- referrals. Referring HOST only: no path, no IP, no fingerprint.
create table if not exists rift_attributions (
  session_id        text primary key,
  agent_id          uuid not null references rift_agents(id) on delete cascade,
  first_source      text,
  first_medium      text,
  first_campaign    text,
  first_referrer    text,
  first_landing     text,
  first_at          timestamptz not null default now(),
  last_source       text,
  last_medium       text,
  last_campaign     text,
  last_referrer     text,
  last_landing      text,
  last_at           timestamptz not null default now(),
  visits            integer not null default 1
);

create or replace function rift_reject_first_touch_change()
returns trigger language plpgsql as $$
begin
  if new.first_source   is distinct from old.first_source
  or new.first_medium   is distinct from old.first_medium
  or new.first_campaign is distinct from old.first_campaign
  or new.first_referrer is distinct from old.first_referrer
  or new.first_landing  is distinct from old.first_landing
  or new.first_at       is distinct from old.first_at then
    raise exception 'first touch is immutable (session %)', old.session_id;
  end if;
  return new;
end $$;

drop trigger if exists rift_first_touch_immutable on rift_attributions;
create trigger rift_first_touch_immutable
  before update on rift_attributions
  for each row execute function rift_reject_first_touch_change();

-- The wording is stored, not referenced. Wording changes; what somebody
-- agreed to does not.
create table if not exists rift_consents (
  id             uuid primary key default gen_random_uuid(),
  agent_id       uuid not null references rift_agents(id) on delete cascade,
  assessment_id  uuid references rift_assessments(id) on delete set null,
  kind           text not null check (kind in ('email','phone')),
  wording        text not null,
  version        text not null,
  granted        boolean not null,
  ip             inet,
  user_agent     text,
  at             timestamptz not null default now()
);
create index if not exists rift_consents_agent_idx on rift_consents (agent_id, at desc);

-- ---------------------------------------------------------------------------
-- Programme registry
-- ---------------------------------------------------------------------------

create table if not exists rift_programs (
  id                uuid primary key default gen_random_uuid(),
  slug              text unique not null,
  name              text not null,
  administrator     text not null,
  type              text not null check (type in ('grant','forgivable','deferred','second-lien')),
  funding_state     text not null default 'open' check (funding_state in ('open','waitlist','closed')),
  amount_min        integer not null,
  amount_max        integer not null,
  -- Null means statewide. One county per row, mirroring `AssistanceProgram` in
  -- lib/core/registry.ts exactly: a text[] here would model reality slightly
  -- better and would buy a permanent mapping layer between the database and the
  -- engine that reads it. One shape, one truth. Widen it deliberately if a
  -- programme genuinely needs a list, and widen the domain type in the same
  -- change.
  county            text,
  first_time_only   boolean not null default false,
  -- When a closed or waitlisted programme is expected to reopen. Shown to the
  -- customer WITH its state rather than hidden, because somebody planning
  -- around money that is not currently available needs to know.
  reopens           text,
  source_note       text not null default '',
  income_limit_note text not null,
  price_cap_note    text not null,
  conditions        text[] not null default '{}',
  source_url        text,
  verified_on       date not null,
  verified_by       text not null,
  active            boolean not null default true,
  created_at        timestamptz not null default now(),
  constraint amounts_ordered check (amount_max >= amount_min)
);
create index if not exists rift_programs_verified_idx on rift_programs (verified_on desc);

create table if not exists rift_program_verifications (
  id          uuid primary key default gen_random_uuid(),
  program_id  uuid not null references rift_programs(id) on delete cascade,
  verified_on date not null,
  verified_by text not null,
  note        text,
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Value delivered
-- ---------------------------------------------------------------------------

-- A readout is an immutable snapshot. `figures` is what they were SHOWN;
-- `inputs` is what produced it, kept so a plan can recompute and disclose the
-- difference rather than silently replacing a number somebody has already told
-- their partner.
create table if not exists rift_readouts (
  id             uuid primary key default gen_random_uuid(),
  agent_id       uuid not null references rift_agents(id) on delete cascade,
  assessment_id  uuid not null references rift_assessments(id) on delete cascade,
  side           text not null check (side in ('buy','sell')),
  share_token    text unique not null,
  inputs         jsonb not null,
  figures        jsonb not null,
  matched        jsonb not null default '[]'::jsonb,
  created_at     timestamptz not null default now()
);
create index if not exists rift_readouts_assessment_idx on rift_readouts (assessment_id);

-- Trust state belongs to a figure, not to a record: a plan routinely holds a
-- lender-verified pre-approval next to a preliminary repair estimate, and a
-- single column on the parent forces one lie or the other.
create table if not exists rift_figures (
  id             uuid primary key default gen_random_uuid(),
  agent_id       uuid not null references rift_agents(id) on delete cascade,
  readout_id     uuid references rift_readouts(id) on delete cascade,
  label          text not null,
  value_cents    bigint not null,
  trust_state    text not null default 'preliminary'
                   check (trust_state in ('preliminary','pending-review','reviewed','verified')),
  ceiling        text not null default 'verified'
                   check (ceiling in ('preliminary','pending-review','reviewed','verified')),
  assumptions    jsonb not null default '[]'::jsonb,
  could_be_wrong text not null,
  confirmed_by   text,
  created_at     timestamptz not null default now(),
  -- A green chip with nobody behind it is the exact false confidence the
  -- trust ladder exists to prevent.
  constraint verified_needs_a_name check (trust_state <> 'verified' or confirmed_by is not null),
  -- Every figure carries its assumptions and its failure mode.
  constraint figures_state_their_assumptions check (jsonb_array_length(assumptions) > 0),
  constraint figures_state_their_failure_mode check (length(could_be_wrong) > 20)
);
create index if not exists rift_figures_readout_idx on rift_figures (readout_id);

-- ---------------------------------------------------------------------------
-- Leads
-- ---------------------------------------------------------------------------

create table if not exists rift_leads (
  id                 uuid primary key default gen_random_uuid(),
  agent_id           uuid not null references rift_agents(id) on delete cascade,
  assessment_id      uuid not null references rift_assessments(id) on delete cascade,
  name               text,
  email              text,
  phone              text,
  side               text not null check (side in ('buy','sell')),
  -- Pins what they were actually asked, so an edit cannot rewrite history.
  funnel_version_id  uuid references rift_funnel_versions(id) on delete set null,
  score              integer,
  band               text check (band in ('now','soon','later','nurture')),
  -- The breakdown, not just the total. An agent who cannot audit a ranking
  -- stops trusting it inside a week.
  signals            jsonb not null default '[]'::jsonb,
  human_replied_at   timestamptz,
  created_at         timestamptz not null default now()
);
create index if not exists rift_leads_agent_idx on rift_leads (agent_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Row level security
-- ---------------------------------------------------------------------------

alter table rift_agents               enable row level security;
alter table rift_business_rules       enable row level security;
alter table rift_funnels              enable row level security;
alter table rift_funnel_versions      enable row level security;
alter table rift_questions            enable row level security;
alter table rift_assessments          enable row level security;
alter table rift_answers              enable row level security;
alter table rift_events               enable row level security;
alter table rift_attributions         enable row level security;
alter table rift_consents             enable row level security;
alter table rift_programs             enable row level security;
alter table rift_program_verifications enable row level security;
alter table rift_readouts             enable row level security;
alter table rift_figures              enable row level security;
alter table rift_leads                enable row level security;

-- Helper: the agent row belonging to the caller.
create or replace function rift_my_agent_id() returns uuid
language sql stable security definer set search_path = public as $$
  select id from rift_agents where auth_user_id = auth.uid() limit 1;
$$;

drop policy if exists rift_agents_self on rift_agents;
create policy rift_agents_self on rift_agents
  for all using (auth_user_id = auth.uid()) with check (auth_user_id = auth.uid());

-- Agent-owned tables: one policy shape, applied consistently.
do $$
declare t text;
begin
  foreach t in array array[
    'rift_business_rules','rift_assessments','rift_events','rift_attributions',
    'rift_consents','rift_readouts','rift_figures','rift_leads','rift_funnels'
  ] loop
    execute format('drop policy if exists %I on %I', t || '_owner', t);
    execute format(
      'create policy %I on %I for all using (agent_id = rift_my_agent_id()) with check (agent_id = rift_my_agent_id())',
      t || '_owner', t);
  end loop;
end $$;

-- Child tables inherit ownership through their parent.
drop policy if exists rift_funnel_versions_owner on rift_funnel_versions;
create policy rift_funnel_versions_owner on rift_funnel_versions for all
  using (exists (select 1 from rift_funnels f where f.id = funnel_id and f.agent_id = rift_my_agent_id()))
  with check (exists (select 1 from rift_funnels f where f.id = funnel_id and f.agent_id = rift_my_agent_id()));

drop policy if exists rift_questions_owner on rift_questions;
create policy rift_questions_owner on rift_questions for all
  using (exists (
    select 1 from rift_funnel_versions v join rift_funnels f on f.id = v.funnel_id
    where v.id = funnel_version_id and f.agent_id = rift_my_agent_id()))
  with check (exists (
    select 1 from rift_funnel_versions v join rift_funnels f on f.id = v.funnel_id
    where v.id = funnel_version_id and f.agent_id = rift_my_agent_id()));

drop policy if exists rift_answers_owner on rift_answers;
create policy rift_answers_owner on rift_answers for all
  using (exists (select 1 from rift_assessments a where a.id = assessment_id and a.agent_id = rift_my_agent_id()))
  with check (exists (select 1 from rift_assessments a where a.id = assessment_id and a.agent_id = rift_my_agent_id()));

-- The registry is public information, and the customer-facing match runs
-- before any account exists.
drop policy if exists rift_programs_public_read on rift_programs;
create policy rift_programs_public_read on rift_programs for select using (true);

drop policy if exists rift_program_verifications_read on rift_program_verifications;
create policy rift_program_verifications_read on rift_program_verifications for select using (true);

-- Writes to the registry, to answers, to events and to attribution go through
-- the service role only. No client-side insert path exists, or the funnel
-- numbers can be poisoned from a browser console.


-- =====================================================================
-- 20260907120000_rift_nurture_review.sql
-- =====================================================================
-- ============================================================================
-- Nurture enrolments, sent touches, and the review queue.
--
-- Additive to 20260907000000_rift_core.sql.
--
-- Two rules are enforced here rather than in application code, because both
-- fail as something a person receives rather than as an error:
--
--   * a touch is recorded once per step per enrolment, so a retry, a double
--     cron fire, or two workers cannot send the same email twice;
--   * nothing reaches `verified` without a named party.
-- ============================================================================

create table if not exists rift_enrolments (
  id           uuid primary key default gen_random_uuid(),
  agent_id     uuid not null references rift_agents(id) on delete cascade,
  lead_id      uuid not null references rift_leads(id) on delete cascade,
  band         text not null check (band in ('now','soon','later','nurture')),
  entered_at   timestamptz not null default now(),
  -- Set the moment any stop condition fires. A live enrolment has none.
  stopped_at   timestamptz,
  stop_reason  text check (stop_reason in ('replied','booked','converted','declined','unsubscribed','bounced')),
  -- Written phone consent gates the channel, never the sequence.
  phone_consent boolean not null default false,
  constraint stop_needs_a_reason check ((stopped_at is null) = (stop_reason is null)),
  -- One live enrolment per lead. Two would send everything twice.
  unique (lead_id)
);
create index if not exists rift_enrolments_due_idx on rift_enrolments (agent_id, stopped_at, entered_at);

create table if not exists rift_touches (
  id            uuid primary key default gen_random_uuid(),
  enrolment_id  uuid not null references rift_enrolments(id) on delete cascade,
  step_id       text not null,
  -- The channel actually used, which may differ from the step's when consent
  -- is missing. The reason is data, not a log line an operator has to go and find.
  channel       text not null check (channel in ('email','text','call','task')),
  downgraded_reason text,
  sent_at       timestamptz not null default now(),
  outcome       text not null default 'sent' check (outcome in ('sent','skipped','failed')),
  detail        text,
  -- The idempotency guarantee. A retry or a second cron worker cannot send the
  -- same step twice, and this is the only place that can promise it.
  unique (enrolment_id, step_id)
);

create table if not exists rift_review_items (
  id           uuid primary key default gen_random_uuid(),
  agent_id     uuid not null references rift_agents(id) on delete cascade,
  readout_id   uuid references rift_readouts(id) on delete set null,
  who          text not null,
  kind         text not null check (kind in ('figure','document','program','plan')),
  what         text not null,
  claim        text not null,
  state        text not null default 'pending-review'
                 check (state in ('preliminary','pending-review','reviewed','verified')),
  ceiling      text not null default 'verified'
                 check (ceiling in ('preliminary','pending-review','reviewed','verified')),
  raised_by    text not null check (raised_by in ('client','agent','system')),
  to_advance   text not null,
  confirmed_by text,
  raised_at    timestamptz not null default now(),
  resolved_at  timestamptz,
  constraint review_verified_needs_a_name check (state <> 'verified' or confirmed_by is not null)
);
create index if not exists rift_review_open_idx on rift_review_items (agent_id, state, raised_at);

alter table rift_enrolments  enable row level security;
alter table rift_touches     enable row level security;
alter table rift_review_items enable row level security;

drop policy if exists rift_enrolments_owner on rift_enrolments;
create policy rift_enrolments_owner on rift_enrolments for all
  using (agent_id = rift_my_agent_id()) with check (agent_id = rift_my_agent_id());

drop policy if exists rift_review_items_owner on rift_review_items;
create policy rift_review_items_owner on rift_review_items for all
  using (agent_id = rift_my_agent_id()) with check (agent_id = rift_my_agent_id());

drop policy if exists rift_touches_owner on rift_touches;
create policy rift_touches_owner on rift_touches for all
  using (exists (select 1 from rift_enrolments e where e.id = enrolment_id and e.agent_id = rift_my_agent_id()))
  with check (exists (select 1 from rift_enrolments e where e.id = enrolment_id and e.agent_id = rift_my_agent_id()));


-- =====================================================================
-- 20260907180000_rift_rates.sql
-- =====================================================================
-- ============================================================================
-- The mortgage rate assumption, given a source and a date.
--
-- BUYER_DEFAULTS.ratePct was 6.5: a literal with no provenance that every
-- monthly figure, every gap and every timeline in the product depends on. A
-- rate that is silently four months old is precisely the "wrong number rather
-- than an error" failure this codebase exists to prevent: nothing breaks, the
-- arithmetic stays correct, and the answer is wrong.
--
-- Snapshots rather than a single mutable row, because the readout is an
-- immutable record of what somebody was told. When a plan later disagrees with
-- their readout, "the rate moved from 6.5% on 19 Aug to 6.75% on 6 Sep" is the
-- explanation, and it only exists if the old value was kept.
-- ============================================================================

create table if not exists rift_rate_snapshots (
  id          uuid primary key default gen_random_uuid(),
  rate_pct    numeric(5,3) not null,
  term_years  integer not null default 30,
  product     text not null default 'conventional-30-fixed',
  source      text not null,
  source_url  text,
  as_of       date not null,
  created_at  timestamptz not null default now(),
  -- A rate outside this band is a data-entry error, not a market event. The
  -- US 30-year has not left it in living memory, and accepting 0.65 for 6.5
  -- would understate somebody's monthly payment by hundreds of dollars.
  constraint rate_is_plausible check (rate_pct > 1 and rate_pct < 20),
  unique (product, as_of)
);
create index if not exists rift_rate_latest_idx on rift_rate_snapshots (product, as_of desc);

alter table rift_rate_snapshots enable row level security;

-- Public read: the rate is displayed to every visitor as an assumption beside
-- the figures it produces, and that happens before any account exists.
drop policy if exists rift_rates_public_read on rift_rate_snapshots;
create policy rift_rates_public_read on rift_rate_snapshots for select using (true);


-- =====================================================================
-- 20260907190000_rift_lead_without_assessment.sql
-- =====================================================================
-- ============================================================================
-- A lead can exist without an assessment.
--
-- `rift_leads.assessment_id` was NOT NULL, which assumed every lead comes from
-- a completed assessment. Two real paths do not:
--
--   * somebody who asks for their readout by email from a page reached by a
--     share link, having never taken the assessment themselves;
--   * somebody who books a call from the landing page.
--
-- The capture failed outright rather than storing the lead without the link:
-- so the most valuable moment in the funnel, a stranger volunteering their
-- address, lost the lead entirely.
-- ============================================================================

alter table rift_leads alter column assessment_id drop not null;


-- =====================================================================
-- 20260907200000_rift_lead_inputs.sql
-- =====================================================================
-- ============================================================================
-- Store what the score was computed FROM, not only what it came to.
--
-- `score` and `signals` were written once at capture and never revisited. One
-- of the six signals is recency, and recency decays, so a lead captured three
-- weeks ago kept the 100 it earned on the day and went on outranking somebody
-- who arrived this morning.
--
-- The ranking is the entire argument for Studio. A ranking that silently goes
-- stale is worse than none: it still costs the agent attention, and it spends
-- it on the wrong people while looking exactly as authoritative as it did when
-- it was right.
--
-- Keeping the inputs lets the score be recomputed on read. The stored score
-- stays as the value at capture, which is worth having: it is what the lead
-- looked like when it arrived, and the difference between the two is itself
-- information.
-- ============================================================================

alter table rift_leads add column if not exists lead_input jsonb;

comment on column rift_leads.lead_input is
  'The LeadInput the score was computed from. Recomputed on read so recency decays; see lib/db/leads.ts.';
comment on column rift_leads.score is
  'The score AT CAPTURE. Studio recomputes for display: do not treat this as current.';


-- =====================================================================
-- 20260907210000_rift_question_types.sql
-- =====================================================================
-- ============================================================================
-- Align the question-type constraint with the domain.
--
-- The constraint allowed 'number' and 'money', which `FieldType` does not have,
-- and rejected 'select' and 'boolean', which it does. So publishing the
-- built-in funnel failed on its very first question (the county select) and
-- the failure was swallowed by a caller that did not check the error.
--
-- Two lessons, both already learned once in this schema and worth the comment
-- so they are not learned a third time: a constraint written from memory rather
-- than from the type it mirrors will drift, and an insert whose error nobody
-- reads is an insert that has not happened.
-- ============================================================================

alter table rift_questions drop constraint if exists rift_questions_type_check;

alter table rift_questions add constraint rift_questions_type_check
  check (type in ('choice', 'slider', 'select', 'text', 'boolean'));


-- =====================================================================
-- 20260907220000_rift_review_figure.sql
-- =====================================================================
-- ============================================================================
-- Link a review item to the figure it is about.
--
-- The trust ladder was described end to end and connected at neither end.
-- Promoting a review item changed the ITEM; the figure the customer is looking
-- at stayed "preliminary" forever, so "Kaleb has been through this" was a fact
-- recorded in Studio and invisible to the only person it was for.
--
-- With the link, advancing an item advances the figure, and a shared readout
-- can show which of its numbers somebody has actually checked.
-- ============================================================================

alter table rift_review_items
  add column if not exists figure_id uuid references rift_figures(id) on delete set null;

create index if not exists rift_review_figure_idx on rift_review_items (figure_id);

comment on column rift_review_items.figure_id is
  'The figure this review is about. Null for a request that predates figure tracking, or one about something not stored as a figure.';


-- =====================================================================
-- 20260907230000_rift_one_live_assessment.sql
-- =====================================================================
-- ============================================================================
-- One live assessment per session, per side.
--
-- `startAssessment` checked for an existing row and inserted if it found none.
-- Between the check and the insert, another request can do the same, and the
-- assessment page fires this on mount, so a double-render, a fast refresh, or a
-- flaky connection retrying is enough.
--
-- Measured before the fix: six concurrent starts produced six assessments for
-- one visitor. Nothing failed. The consequences are all quiet ones: the agent
-- sees six abandoned people where there was one, five sets of answers are
-- orphaned against ids the client discarded, and any completion rate computed
-- from assessments is wrong by whatever the retry rate happens to be.
--
-- A check-then-insert cannot be made safe in application code. Only the
-- database can refuse the second one.
-- ============================================================================

-- Deduplicate before adding the constraint: keep the oldest live assessment
-- per session and side, and delete the rest. Answers cascade with them, which
-- is correct: they are attached to rows the client already abandoned.
delete from rift_assessments a
using rift_assessments b
where a.completed_at is null
  and b.completed_at is null
  and a.agent_id = b.agent_id
  and a.session_id = b.session_id
  and a.side = b.side
  and a.started_at > b.started_at;

create unique index if not exists rift_one_live_assessment
  on rift_assessments (agent_id, session_id, side)
  where completed_at is null;

comment on index rift_one_live_assessment is
  'A visitor has one live assessment per side. startAssessment relies on this to make its check-then-insert safe under concurrency.';


-- =====================================================================
-- 20260908000000_rift_lead_survives_assessment.sql
-- =====================================================================
-- ============================================================================
-- A lead is not a side effect of its assessment.
--
-- `rift_leads.assessment_id` cascaded on delete, so the retention sweep: whose
-- stated job is deleting an assessment nobody came back to: silently took the
-- LEAD with it: the person's contact details, their score, their enrolment,
-- every touch already sent, and the link to their consent record.
--
-- Nobody chose that. It was a foreign key default doing something the retention
-- policy never described, and it would have removed relationships the agent was
-- still working.
--
-- The column is already nullable: a lead can exist without an assessment,
-- because somebody opening a shared readout never took one. So SET NULL is both
-- available and correct: the assessment goes on schedule, the person remains,
-- and deleting a person becomes a deliberate act rather than a consequence.
-- ============================================================================

alter table rift_leads drop constraint if exists rift_leads_assessment_id_fkey;

alter table rift_leads
  add constraint rift_leads_assessment_id_fkey
  foreign key (assessment_id) references rift_assessments(id) on delete set null;

comment on column rift_leads.assessment_id is
  'Null when the assessment has been deleted by retention, or when the lead never had one. Deleting a lead is deliberate: see lib/db/retention.ts.';


-- =====================================================================
-- 20260908010000_rift_agent_survives_login.sql
-- =====================================================================
-- ============================================================================
-- Deleting a login must not delete the business.
--
-- `rift_agents.auth_user_id` cascaded from `auth.users`. Every other table
-- cascades from `rift_agents`. So removing one row in Supabase's Authentication
-- panel (a routine admin action, and an easy misclick) would have deleted
-- every assessment, lead, consent record, readout, figure, enrolment and event
-- in the product.
--
-- Consent records are the part that makes this unrecoverable rather than merely
-- catastrophic: they are the evidence that contacting those people was lawful,
-- and they cannot be reconstructed from a backup of anything else.
--
-- A login is a way in. The book of business is not attached to it.
--
-- SET NULL leaves the agent row unlinked, which the sign-in path already treats
-- correctly: `currentAgent()` returns null for a user with no agent row, and
-- the bootstrap re-links with --auth-user-id.
-- ============================================================================

alter table rift_agents drop constraint if exists rift_agents_auth_user_id_fkey;

alter table rift_agents
  add constraint rift_agents_auth_user_id_fkey
  foreign key (auth_user_id) references auth.users(id) on delete set null;

comment on column rift_agents.auth_user_id is
  'The login. Null if that login was deleted: the agent and everything belonging to them survives. Re-link with scripts/bootstrap-rift.mjs --auth-user-id.';


-- =====================================================================
-- 20260908020000_rift_funnel_report.sql
-- =====================================================================
-- ============================================================================
-- Aggregate the funnel report in the database.
--
-- It was fetching every matching event and counting distinct sessions in
-- JavaScript. At a year of traffic that is 45,000 rows over the wire to produce
-- seven numbers, on every Studio load. At five years it is a page that times
-- out, and the failure arrives exactly when the data finally means something.
--
-- The window matters more than the speed. The report had no time bound, so it
-- mixed last year's funnel with this week's, and the whole point of measuring
-- drop-off is to change a question and see whether it helped. Averaged against
-- twelve months of the old wording, it never will.
-- ============================================================================

create or replace function rift_funnel_report(
  p_agent uuid,
  p_side text,
  p_days integer default 90
)
returns table (
  question_key text,
  reached integer,
  answered integer,
  median_dwell_ms integer
)
language sql
stable
security definer
set search_path = public
as $$
  with windowed as (
    select session_id, name, question_key, dwell_ms
    from rift_events
    where agent_id = p_agent
      and side = p_side
      and at >= now() - (p_days || ' days')::interval
      and name in ('question_view', 'question_answer')
      and question_key is not null
  )
  select
    w.question_key,
    count(distinct w.session_id) filter (where w.name = 'question_view')::integer,
    count(distinct w.session_id) filter (where w.name = 'question_answer')::integer,
    /* The median, not the mean. One person who left a tab open for an hour
       would otherwise turn "they read it and declined" into "they bounced off
       it" for everybody else: and those two want opposite remedies. */
    coalesce(
      percentile_cont(0.5) within group (order by w.dwell_ms)
        filter (where w.name = 'question_answer' and w.dwell_ms is not null),
      0
    )::integer
  from windowed w
  group by w.question_key;
$$;

create or replace function rift_funnel_starts(
  p_agent uuid,
  p_side text,
  p_days integer default 90
)
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select count(distinct session_id)::integer
  from rift_events
  where agent_id = p_agent
    and side = p_side
    and at >= now() - (p_days || ' days')::interval
    and name = 'assessment_start';
$$;

-- The report reads a narrow slice by agent, side and recency. Without this it
-- is a sequential scan over every event ever recorded.
create index if not exists rift_events_report_idx
  on rift_events (agent_id, side, at desc)
  where question_key is not null;

-- Granted only to roles that exist. Supabase provides `anon` and
-- `authenticated`; the local test harness has neither by default, and a
-- migration that cannot run locally is a migration nobody tests.
do $$
declare r text;
begin
  foreach r in array array['anon', 'authenticated'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('grant execute on function rift_funnel_report(uuid, text, integer) to %I', r);
      execute format('grant execute on function rift_funnel_starts(uuid, text, integer) to %I', r);
    end if;
  end loop;
end $$;


-- =====================================================================
-- 20260909000000_rift_manage_real_people.sql
-- =====================================================================
-- ============================================================================
-- Managing people who never took an assessment.
--
-- Everything built so far assumes a lead ARRIVES: somebody completes a funnel,
-- /api/capture writes the row, and the score explains why they matter. That is
-- the only door into rift_leads, which means an agent with ten existing
-- relationships has no way to put them in the product that exists to manage
-- them.
--
-- Three things were missing, and none of them are the funnel's fault:
--
--   A STAGE. `band` is computed urgency (now/soon/later/nurture) derived
--   from answers and recency. It is not where somebody IS. A person under
--   contract and a person who filled in a form this morning can both be
--   'now', and an agent cannot run a business off that.
--
--   A RECORD OF CONTACT. rift_touches is bound to an enrolment and unique per
--   step, because its job is guaranteeing an automated sequence never sends
--   twice. It physically cannot hold "called Tuesday, she is pre-approved to
--   340": and that sentence is the most valuable data in a solo practice.
--
--   A BASIS FOR CONTACTING THEM. A lead from the funnel consented on the way
--   in, and that consent is recorded. A lead typed in by hand has no such
--   record, and "I know them" is not a thing the system should infer on the
--   agent's behalf. It is asked for and stored.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Where somebody actually is
-- ---------------------------------------------------------------------------

alter table rift_leads add column if not exists stage text;
alter table rift_leads add column if not exists stage_since timestamptz;
alter table rift_leads add column if not exists source text not null default 'funnel';
alter table rift_leads add column if not exists contact_basis text;
alter table rift_leads add column if not exists archived_at timestamptz;
alter table rift_leads add column if not exists archived_reason text;

-- The stage vocabulary is closed. A lead sitting in 'Under Contract' while the
-- board filters for 'Under contract' does not error and does not appear: it
-- silently stops being part of the business. That is the exact failure mode
-- this codebase keeps finding, so the database refuses the typo instead.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_leads_stage_check') then
    alter table rift_leads add constraint rift_leads_stage_check check (
      stage is null or stage in (
        'Exploring','Building readiness','Preparing the property','Financing',
        'Ready to shop','Searching','Reviewing offers','Under contract','Closing',
        'Closed','Lost'
      )
    );
  end if;
end $$;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_leads_source_check') then
    alter table rift_leads add constraint rift_leads_source_check
      check (source in ('funnel','manual','referral','import'));
  end if;
end $$;

-- A stage without a date is a stage that cannot go stale, and stall detection
-- is the whole reason the stage exists. They are set together or not at all.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_leads_stage_dated') then
    alter table rift_leads add constraint rift_leads_stage_dated
      check ((stage is null) = (stage_since is null));
  end if;
end $$;

-- Somebody typed in by hand has no assessment to justify contacting them, so
-- the basis is required at the point of entry rather than assumed later.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_leads_manual_needs_basis') then
    alter table rift_leads add constraint rift_leads_manual_needs_basis
      check (source = 'funnel' or contact_basis is not null);
  end if;
end $$;

-- Reaching anybody needs a way to reach them. A funnel lead always has an
-- email; a hand-entered one must have at least one of the two, or the record
-- is a note to self wearing a person's name.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_leads_reachable') then
    alter table rift_leads add constraint rift_leads_reachable
      check (source = 'funnel' or email is not null or phone is not null);
  end if;
end $$;

create index if not exists rift_leads_stage_idx
  on rift_leads (agent_id, stage, stage_since)
  where archived_at is null;

-- ---------------------------------------------------------------------------
-- What was said, and when
-- ---------------------------------------------------------------------------

create table if not exists rift_lead_notes (
  id         uuid primary key default gen_random_uuid(),
  lead_id    uuid not null references rift_leads(id) on delete cascade,
  agent_id   uuid not null references rift_agents(id) on delete cascade,
  -- What kind of contact this was. 'note' is a thought, the rest happened.
  kind       text not null check (kind in ('note','call','email','text','meeting','stage')),
  body       text not null check (length(btrim(body)) > 0),
  -- Set only on kind='stage', so the history explains its own movements
  -- rather than leaving an agent to infer them from timestamps.
  from_stage text,
  to_stage   text,
  at         timestamptz not null default now()
);

create index if not exists rift_lead_notes_lead_idx
  on rift_lead_notes (lead_id, at desc);

-- A note cannot be edited or deleted through the app. The value of a contact
-- record is that it is what was actually written at the time; one that can be
-- tidied up later is a record of the agent's current opinion instead.
comment on table rift_lead_notes is
  'Append-only from the application. What was said, when, on which channel.';

-- ---------------------------------------------------------------------------
-- Row level security, matching every other table
-- ---------------------------------------------------------------------------

alter table rift_lead_notes enable row level security;

do $$
begin
  if not exists (
    select 1 from pg_policies
    where tablename = 'rift_lead_notes' and policyname = 'rift_lead_notes_own'
  ) then
    create policy rift_lead_notes_own on rift_lead_notes
      using (agent_id = rift_my_agent_id())
      with check (agent_id = rift_my_agent_id());
  end if;
end $$;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    grant select, insert on rift_lead_notes to authenticated;
  end if;
end $$;


-- =====================================================================
-- 20260910000000_rift_next_action.sql
-- =====================================================================
-- ============================================================================
-- The next thing you owe them, and when.
--
-- The board says who has gone quiet. It cannot say what you decided to do about
-- it, so the decision lives in the agent's head between sessions, which is
-- exactly where it gets lost. "Call Marcus Thursday" is the smallest unit of
-- account management and there was nowhere to put it.
--
-- One open action per person, deliberately. A queue of six things owed to the
-- same client is a queue nobody works; the next call is the only one that
-- matters and the rest are notes. Completing an action writes to the history,
-- so what was owed and when it was done stays auditable.
-- ============================================================================

alter table rift_leads add column if not exists next_action text;
alter table rift_leads add column if not exists next_due date;

-- An action with no date is a wish, and a date with no action is an alarm
-- nobody can act on. They travel together or not at all.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_leads_next_action_dated') then
    alter table rift_leads add constraint rift_leads_next_action_dated
      check ((next_action is null) = (next_due is null));
  end if;
end $$;

-- Ordered by what is owed soonest, and only for people still being worked.
create index if not exists rift_leads_due_idx
  on rift_leads (agent_id, next_due)
  where next_due is not null and archived_at is null;

comment on column rift_leads.next_action is
  'The one thing owed to this person next. Cleared when done; the completion is written to rift_lead_notes.';


-- =====================================================================
-- 20260920000000_rift_attribution_sweep_index.sql
-- =====================================================================
-- The index the retention sweep has always needed and never had.
--
-- `rift_attributions` is keyed on session_id, which serves every read in the
-- product except one: the sweep deletes by (agent_id, first_at), and the
-- health check asks the same question to find out whether the sweep is still
-- running. Both are sequential scans today.
--
-- It does not hurt yet, because the analytics window is twenty-four months and
-- the table is small. It starts hurting on the first day that window fires
-- against a table with real traffic in it, which is exactly the day nobody
-- will be watching the retention job, and a deletion job that times out is a
-- deletion job that silently stops keeping the promise printed at the bottom
-- of every readout.
--
-- No RLS change: the policy on this table is unchanged and still the one from
-- 20260907000000_rift_core.sql. An index is not a grant.
create index if not exists rift_attributions_sweep_idx
  on rift_attributions (agent_id, first_at);


-- =====================================================================
-- 20260920010000_rift_events_allowlist.sql
-- =====================================================================
-- Telemetry: an allowlist in the database, and a clean-up of what the
-- blocklist let through.
--
-- `events_carry_no_answer` rejected three literal key names: value, answer,
-- input, and was described in the code as the only real guarantee behind the
-- rule that telemetry stores question ids and timings, never answer values.
-- It was a blocklist, and a blocklist fails open.
--
-- What went through it: the buyers-abroad landing page sent the visitor's
-- residency situation (citizen / resident / ITIN / no U.S. status) under the
-- key `status`, on every page view. Residency status is about as close a
-- proxy for national origin as this product could collect, national origin is
-- a protected class under the Fair Housing Act, and rift_events is keyed on a
-- session that joins to a lead. The page was designed to target a situation
-- rather than an ethnicity and then logged the situation.
--
-- Two things here, in this order, because the second cannot be added while the
-- first is still true of existing rows.

-- 1. Remove what should never have been collected.
--
--    Rewrites every payload to contain only allowed keys. This is deletion,
--    not masking: the values are gone from the row rather than hidden behind
--    a flag, which is the same standard the retention job is held to.
update rift_events e
   set payload = coalesce(
         (select jsonb_object_agg(k, v)
            from jsonb_each(e.payload) as t(k, v)
           where k = any (array[
             'page','qid','step','of','from','via',
             'answered','matched','source','band','prefilled','live',
             'hasTopic','delivered','consent','slot'
           ])),
         '{}'::jsonb)
 where exists (
       select 1
         from jsonb_object_keys(e.payload) as k
        where k <> all (array[
          'page','qid','step','of','from','via',
          'answered','matched','source','band','prefilled','live',
          'hasTopic','delivered','consent','slot'
        ])
 );

-- 2. Make it impossible to write again.
--
--    `payload - array[...]` removes every allowed key; if anything is left,
--    the row carried a key nobody approved and it is rejected. Adding a key
--    to telemetry now requires a migration, which is precisely the moment
--    somebody should have to decide whether it is an answer.
--
--    The list is kept identical to ALLOWED_META in lib/core/telemetry.ts, and
--    lib/core/telemetry.test.ts fails when the two drift apart.
alter table rift_events drop constraint if exists events_carry_no_answer;

alter table rift_events add constraint events_carry_no_answer check (
  payload - array[
    'page','qid','step','of','from','via',
    'answered','matched','source','band','prefilled','live',
    'hasTopic','delivered','consent','slot'
  ] = '{}'::jsonb
);

-- No RLS change. The policy on rift_events is unchanged and still the one from
-- 20260907000000_rift_core.sql; a constraint is not a grant.


-- =====================================================================
-- 20260920020000_rift_forget_reaches_the_lead.sql
-- =====================================================================
-- ============================================================================
-- "Delete all of it" did not reach the person.
--
-- `forget()` deletes the assessment, the events and the attribution for a
-- session, and its own docblock says it "is the same deletion the sweep
-- performs, triggered by the person rather than by time". That was true when
-- it was written: rift_leads.assessment_id cascaded, so deleting the
-- assessment took the lead with it.
--
-- 20260908000000 changed that cascade to SET NULL, for a good and carefully
-- argued reason: the retention sweep was destroying relationships the agent
-- was still working, as a side effect of a foreign key default. That fix is
-- right and stays. What nobody noticed is that `forget()` shares the
-- mechanism: from that migration onwards, a person clicking "Delete all of
-- it" had their assessment removed and their NAME, EMAIL, PHONE and CONSENT
-- RECORD left behind, while the page told them "Nothing about this visit is
-- left on this device or on our side."
--
-- The sweep was updated to delete leads explicitly. `forget()` was not.
--
-- Two problems here, and this file is the half that needs the database:
--
--   1. A lead captured with no assessment: from the abroad readout, or from
--      /book on a landing page: has no link to a session at all, so nothing
--      could find it even after the code is fixed. rift_leads gets its own
--      session_id.
--
--   2. Same for the consent record, which hangs off the assessment and is
--      SET NULL for the same reason.
--
-- Nullable, because every lead already in the table predates this and there
-- is no honest value to backfill. A null session_id means "captured before
-- this existed, or captured by something that had no session": and the one
-- thing that must never happen is inventing a session id that would make an
-- unrelated person's delete request destroy this row.
-- ============================================================================

alter table rift_leads     add column if not exists session_id text;
alter table rift_consents  add column if not exists session_id text;

create index if not exists rift_leads_session_idx
  on rift_leads (session_id) where session_id is not null;

create index if not exists rift_consents_session_idx
  on rift_consents (session_id) where session_id is not null;

comment on column rift_leads.session_id is
  'The browser session that produced this lead. Nullable for rows captured before 20260920020000. Used by lib/db/retention.ts forget() so that erasure reaches a lead with no assessment behind it.';

comment on column rift_consents.session_id is
  'As rift_leads.session_id. A consent record is evidence that contact was lawful; when the person it is about is erased, there is nobody left for it to be evidence about, so it goes with them.';


-- =====================================================================
-- 20260920030000_rift_client_plan.sql
-- =====================================================================
-- ============================================================================
-- The client's half of the product.
--
-- Rift is described as a client-experience platform. Until now everything it
-- holds points one way: the agent can see the person, the person can see one
-- frozen readout at /r/<token> and nothing after it. From the moment somebody
-- becomes a client, the product they were sold goes dark.
--
-- This is the first surface that points the other way: a plan they can open
-- and read: what has been agreed, who owes what, and by when.
--
-- TWO DECISIONS WORTH STATING.
--
-- No accounts. The whole funnel works without one and it would be strange to
-- demand a password at the moment somebody starts trusting you. Reached by an
-- unguessable token, like the shared readout, and the page is noindex: a link
-- unguessable to a person is trivially findable by a crawler given it.
--
-- The agent's notes are NOT here and must never be. rift_lead_notes is his
-- record of the relationship, including the parts that are his judgement about
-- somebody. A plan item is written to be read by the client; a note is not,
-- and a product that blurs the two teaches an agent to stop writing honestly.
-- ============================================================================

-- The client's door. Nullable: it exists only once the agent has decided to
-- open one, and a token minted for everybody would be a link to a plan nobody
-- has written.
alter table rift_leads add column if not exists client_token text;

create unique index if not exists rift_leads_client_token_idx
  on rift_leads (client_token) where client_token is not null;

comment on column rift_leads.client_token is
  'Unguessable handle for this person''s own plan at /plan/<token>. Null until the agent opens one. Revoked by setting it back to null, which breaks every copy of the link at once.';

create table if not exists rift_plan_items (
  id          uuid primary key default gen_random_uuid(),
  agent_id    uuid not null references rift_agents(id) on delete cascade,
  lead_id     uuid not null references rift_leads(id) on delete cascade,

  -- Written for the client to read. Length-bounded because it is rendered on
  -- their page and a paragraph in a checklist is a paragraph nobody reads.
  title       text not null check (length(btrim(title)) between 3 and 160),

  -- Who it is waiting on. Three values and no default: an item with no owner
  -- is the thing every plan dies of, and making the agent choose is the point.
  -- 'other' carries a name, because "waiting on the county" and "waiting on
  -- your lender" are different kinds of waiting to the person reading it.
  owner       text not null check (owner in ('client','agent','other')),
  owner_name  text check (owner <> 'other' or length(btrim(coalesce(owner_name,''))) > 0),

  -- Optional. A date invented to look organised is worse than no date, because
  -- the client then measures you against it.
  due_on      date,
  done_at     timestamptz,

  -- The agent's order, not a computed one. He knows what comes first.
  sort        integer not null default 0,

  created_at  timestamptz not null default now()
);

create index if not exists rift_plan_items_lead_idx
  on rift_plan_items (lead_id, sort, created_at);

comment on table rift_plan_items is
  'One step of a client''s plan, written to be read by them. Not the agent''s notes: see rift_lead_notes, which stays private.';

alter table rift_plan_items enable row level security;

-- The agent owns them. The client reads through the service role by token, the
-- same way the shared readout does: there is no client session to write a
-- policy against, and inventing one would mean accounts.
drop policy if exists rift_plan_items_owner on rift_plan_items;
create policy rift_plan_items_owner on rift_plan_items for all
  using (agent_id in (select id from rift_agents where auth_user_id = auth.uid()))
  with check (agent_id in (select id from rift_agents where auth_user_id = auth.uid()));


-- =====================================================================
-- 20260920040000_rift_offers.sql
-- =====================================================================
-- ============================================================================
-- Offers, compared by what actually reaches the seller.
--
-- The argument is the same one the rest of the product makes, applied to the
-- last decision in the transaction: a list price is not what reaches you, and
-- neither is a headline offer. Concessions, a repair credit and a rate buy-down
-- all come out of the same number, and the offer that looked $8,000 higher can
-- arrive $3,000 lower.
--
-- NOTHING REACHES THE SELLER UNTIL IT IS RELEASED. `released_at` is null by
-- default and the client's page reads only released rows. An offer arrives
-- while the agent is driving; presenting it unreviewed is how somebody replies
-- to a number before anybody has read the terms under it.
--
-- Money is stored in CENTS. Every other money column in this schema is numeric
-- and that has been survivable, but an offer comparison subtracts six figures
-- from six figures and then ranks the differences, which is precisely where a
-- binary float puts a dollar in the wrong place and changes which offer wins.
-- ============================================================================

create table if not exists rift_offers (
  id            uuid primary key default gen_random_uuid(),
  agent_id      uuid not null references rift_agents(id) on delete cascade,
  -- The seller. An offer belongs to the person selling, not to the buyer.
  lead_id       uuid not null references rift_leads(id) on delete cascade,

  -- As the seller would say it. Not a legal party name.
  offered_by    text not null check (length(btrim(offered_by)) between 2 and 120),

  price_cents         bigint not null check (price_cents > 0),
  -- What the buyer asks the seller to give back. Both non-negative: a negative
  -- concession is money flowing the wrong way and is not a thing.
  concessions_cents   bigint not null default 0 check (concessions_cents >= 0),
  repair_credit_cents bigint not null default 0 check (repair_credit_cents >= 0),
  earnest_cents       bigint not null default 0 check (earnest_cents >= 0),

  financing     text not null check (financing in ('cash','conventional','fha','va','usda','other')),
  close_on      date,
  contingencies text[] not null default '{}',

  -- Whether the buyer supplied proof they can pay. Facts about the paperwork,
  -- never a judgement about the buyer.
  preapproval    boolean not null default false,
  proof_of_funds boolean not null default false,

  -- The agent's words to the seller, shown only once released.
  note          text check (note is null or length(note) <= 2000),

  released_at   timestamptz,
  created_at    timestamptz not null default now()
);

create index if not exists rift_offers_lead_idx on rift_offers (lead_id, created_at desc);
create index if not exists rift_offers_released_idx
  on rift_offers (lead_id) where released_at is not null;

comment on table rift_offers is
  'One offer on a seller''s property. Ranked by net to seller, never by headline price. Invisible to the client until released_at is set.';
comment on column rift_offers.released_at is
  'Null until the agent releases it. The client''s page at /plan/<token> reads only released rows.';

alter table rift_offers enable row level security;

drop policy if exists rift_offers_owner on rift_offers;
create policy rift_offers_owner on rift_offers for all
  using (agent_id in (select id from rift_agents where auth_user_id = auth.uid()))
  with check (agent_id in (select id from rift_agents where auth_user_id = auth.uid()));

-- The seller's own fixed costs, so the offer table and their readout cannot
-- disagree about the same house. Nullable: unknown until somebody says.
alter table rift_leads add column if not exists payoff_cents bigint check (payoff_cents is null or payoff_cents >= 0);
alter table rift_leads add column if not exists commission_pct numeric(5,3) check (commission_pct is null or (commission_pct >= 0 and commission_pct <= 20));

comment on column rift_leads.payoff_cents is
  'What this seller still owes. Feeds the offer comparison. Null means nobody has said, and the comparison says so rather than assuming zero.';


-- =====================================================================
-- 20260921010000_rift_referral_moments.sql
-- =====================================================================
-- ============================================================================
-- The referral engine, given somewhere to remember things.
--
-- `lib/core/referral.ts` has described eight moments, their triggers and the
-- private satisfaction gate since before any of this was built, and until now
-- nothing read it. docs/benchmark.md gives referral and retention a weight of
-- 15 out of 100 (a seventh of the product's own grade) and the shipped
-- product scored approximately nothing on it, because a closing produced a
-- commission and no next relationship.
--
-- THE RULE THIS SCHEMA EXISTS TO ENFORCE.
--
-- Nothing public is asked for before a private check. Every moment that would
-- put a client in front of strangers: the closing-day review, the six-month
-- ask, the anniversary: is gated behind one private question, and an unhappy
-- client is routed to Kaleb rather than to a review form. That is not review
-- gating to manufacture ratings: somebody who says they are unhappy is never
-- asked for a public rating at all, and the private route exists so the
-- complaint gets answered.
--
-- `mood` is the column that check writes to, and it is deliberately nullable
-- with no default. Unanswered is its own state and must not be mistaken for
-- fine: a default of 'good' would ask the entire back catalogue for reviews
-- on the first deployment.
-- ============================================================================

-- The private satisfaction check. Null means nobody has asked yet.
alter table rift_leads add column if not exists mood text
  check (mood is null or mood in ('good', 'mixed', 'bad'));
alter table rift_leads add column if not exists mood_at timestamptz;

comment on column rift_leads.mood is
  'Answer to the private satisfaction check. NULL means unasked, which is not the same as fine: no public ask may go out on a NULL. See gate() in lib/core/referral.ts.';

-- The closing date, as its own fact.
--
-- `stage_since` was nearly good enough: a lead sitting in 'Closed' entered it
-- on the closing day. Nearly, because stage_since is rewritten by any later
-- stage change, and the whole post-closing cadence: thirty days, six months,
-- every anniversary indefinitely: is counted from this date. A correction to
-- somebody's stage two years later would silently move all of their
-- anniversaries, and the only visible symptom would be a message arriving on
-- the wrong day.
alter table rift_leads add column if not exists closed_on date;

comment on column rift_leads.closed_on is
  'The closing date. Every post-closing moment is counted from here rather than from stage_since, which a later stage edit would move.';

-- D5.5, the referral attribution loop: a referred lead linked to its referrer,
-- visible and countable. One column, self-referencing.
--
-- ON DELETE SET NULL rather than CASCADE. Somebody exercising their right to
-- be forgotten must not take the people they referred with them: those are
-- separate relationships who consented separately, and deleting them would be
-- doing a second thing to a third party on the strength of one person's
-- request. The referred lead survives with no referrer, which is the honest
-- record of what is left.
alter table rift_leads add column if not exists referred_by uuid
  references rift_leads(id) on delete set null;

create index if not exists rift_leads_referred_by_idx
  on rift_leads (referred_by) where referred_by is not null;

comment on column rift_leads.referred_by is
  'The relationship that sent this one. SET NULL on delete: erasing a referrer must not erase the people they referred.';

create table if not exists rift_referral_moments (
  id          uuid primary key default gen_random_uuid(),
  agent_id    uuid not null references rift_agents(id) on delete cascade,
  lead_id     uuid not null references rift_leads(id) on delete cascade,

  moment_id   text not null check (moment_id in (
                'value_delivered', 'plan_published', 'financing_secured',
                'under_contract', 'closing_day', 'day_30', 'month_6', 'anniversary')),

  -- Which time round. Zero for the seven moments that happen once.
  --
  -- The anniversary repeats every year on the closing date, indefinitely. A
  -- record keyed on the moment alone would mark the first anniversary sent and
  -- then suppress every anniversary after it: a cadence that quietly stops
  -- after year one while every screen goes on showing it as running. That is
  -- this product's recurring failure shape, and one integer removes it.
  occurrence  integer not null default 0 check (occurrence >= 0),

  state       text not null check (state in
                ('waiting', 'due', 'sent', 'acted', 'declined', 'held')),

  -- Why, in the agent's own words. Held-back moments are the ones worth
  -- explaining to yourself six months later.
  note        text check (note is null or length(note) <= 500),

  decided_at  timestamptz not null default now(),
  created_at  timestamptz not null default now(),

  -- One decision per moment per occurrence. This is what makes recording a
  -- decision idempotent, so a retried request cannot produce two answers about
  -- the same moment and leave the reader to pick.
  unique (lead_id, moment_id, occurrence)
);

create index if not exists rift_referral_moments_lead_idx
  on rift_referral_moments (lead_id, moment_id, occurrence);

comment on table rift_referral_moments is
  'A decision Kaleb has taken about one referral moment. Absence means undecided: the state is then derived from lifecycle data by momentsFor() rather than stored, so a moment becomes due on its own.';

alter table rift_referral_moments enable row level security;

drop policy if exists rift_referral_moments_owner on rift_referral_moments;
create policy rift_referral_moments_owner on rift_referral_moments for all
  using (agent_id in (select id from rift_agents where auth_user_id = auth.uid()))
  with check (agent_id in (select id from rift_agents where auth_user_id = auth.uid()));


-- =====================================================================
-- 20260921030000_rift_referral_attribution.sql
-- =====================================================================
-- Referral attribution: the writer for a column that had none.
--
-- 20260921010000 added rift_leads.referred_by, a Studio screen that counts it,
-- and referralLinks() to read it. Nothing in the product could ever set it.
-- Three reads, zero writes: so "advocacy share of pipeline", the first of the
-- three metrics docs/vision.md names as mattering most and the one with a 30%
-- target by month 12, was not merely at zero. It was incapable of being
-- anything else.
--
-- This adds the handle a referrer passes on, the field that carries it through
-- a visit, and the two constraints that stop attribution rewriting itself.

-- ---------------------------------------------------------------------------
-- The handle
-- ---------------------------------------------------------------------------

-- Deliberately NOT client_token. That one opens somebody's plan: it is a
-- credential, and the whole point of this column is to be given away. Handing
-- a friend a link that shows them your payoff, your stage and every step your
-- agent owes you is not a referral mechanism, it is a disclosure.
alter table rift_leads add column if not exists referral_token text;

-- A DEFAULT rather than an application write.
--
-- The alternative was minting one the first time the agent opened the record,
-- which works and adds a write to a read path plus one more thing that can
-- fail. A column default costs nothing, cannot be forgotten by a new insert
-- path, and means the handle exists from the moment the person does. Crucially
-- it also does not appear in any INSERT statement, so a deploy that lands
-- before this migration is unaffected: the column simply is not there yet.
alter table rift_leads
  alter column referral_token set default encode(gen_random_bytes(12), 'hex');

create unique index if not exists rift_leads_referral_token_idx
  on rift_leads (referral_token) where referral_token is not null;

comment on column rift_leads.referral_token is
  'Public handle this person hands to somebody else. Appears in a URL as ?r=. Never opens anything: it only records who sent the visitor. See client_token for the credential.';

-- ---------------------------------------------------------------------------
-- Carrying it through the visit
-- ---------------------------------------------------------------------------

-- A referral is a first touch. Somebody arrives on a friend's link, reads for
-- ten minutes, leaves, comes back a week later through a Google search and
-- finally finishes the assessment: the friend sent them, and an attribution
-- model that credits the search has just told the agent to buy more search.
alter table rift_attributions add column if not exists first_ref text;
alter table rift_attributions add column if not exists last_ref  text;

comment on column rift_attributions.first_ref is
  'The ?r= value on the visitor''s FIRST touch. Immutable, like every other first_* column: enforced by rift_reject_first_touch_change().';

-- The trigger names its columns one by one, so a new first_* column is not
-- covered until it is added here. Adding the column without this is the whole
-- bug class: a guarantee that silently stops applying to the newest field.
create or replace function rift_reject_first_touch_change()
returns trigger language plpgsql as $$
begin
  if new.first_source   is distinct from old.first_source
  or new.first_medium   is distinct from old.first_medium
  or new.first_campaign is distinct from old.first_campaign
  or new.first_referrer is distinct from old.first_referrer
  or new.first_landing  is distinct from old.first_landing
  or new.first_ref      is distinct from old.first_ref
  or new.first_at       is distinct from old.first_at then
    raise exception 'first touch is immutable (session %)', old.session_id;
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Who sent them is written once
-- ---------------------------------------------------------------------------

-- Same reasoning as first touch, and it matters more here. A referral is the
-- highest-margin relationship an agent has; re-pointing one at a later channel
-- would make the cheapest source in the business look like the weakest.
--
-- WHAT IS REJECTED IS RE-POINTING, NOT CLEARING, and the difference is not a
-- softening: the first version of this rejected both and broke erasure.
--
-- referred_by is `on delete set null`. A foreign-key SET NULL action fires
-- row-level UPDATE triggers, so a trigger that refused every change to a
-- non-null referred_by refused the cascade too, and DELETING A REFERRER
-- FAILED. That is "delete all of it": the strongest promise this product
-- makes and the one with a legal obligation behind it: broken by a
-- correctness guarantee about attribution, and it would have surfaced at the
-- worst possible moment: somebody exercising their erasure right, on a person
-- whose only distinguishing feature is that somebody else liked the product
-- enough to pass it on.
--
-- So:
--   NULL -> a value          allowed. The lead row is created first and the
--                            referrer resolved immediately afterwards.
--   a value -> a DIFFERENT   rejected. This is attribution being rewritten,
--   value                    and it is the only case that corrupts anything.
--   a value -> NULL          allowed. Either the referrer was deleted, or the
--                            link is being withdrawn. Neither is a lie about
--                            where a relationship came from; it is the absence
--                            of a claim.
create or replace function rift_reject_referrer_change()
returns trigger language plpgsql as $$
begin
  if old.referred_by is not null
     and new.referred_by is not null
     and new.referred_by is distinct from old.referred_by then
    raise exception 'who referred a lead cannot be repointed (lead %)', old.id;
  end if;
  return new;
end $$;

drop trigger if exists rift_referrer_is_immutable on rift_leads;
create trigger rift_referrer_is_immutable
  before update on rift_leads
  for each row execute function rift_reject_referrer_change();

-- Nobody refers themselves. Cheap to state, and the alternative is a
-- self-referential row that renders as a person who sent themselves in.
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'rift_leads_no_self_referral'
  ) then
    alter table rift_leads add constraint rift_leads_no_self_referral
      check (referred_by is null or referred_by <> id);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Backfill
-- ---------------------------------------------------------------------------

-- Everybody already in the book gets a handle, so the agent can send a
-- referral link to a client he closed last month rather than only to people
-- who arrive after this migration.
update rift_leads
   set referral_token = encode(gen_random_bytes(12), 'hex')
 where referral_token is null;

create index if not exists rift_leads_referred_by_idx2
  on rift_leads (agent_id, referred_by) where referred_by is not null;


-- =====================================================================
-- 20260921040000_rift_representation.sql
-- =====================================================================
-- Representation: the gate between a lead and a client.
--
-- docs/product.md requires this to be "a visible lifecycle state rather than
-- an offline side channel". It was neither: there was no column at all, which
-- is why canPublish() in lib/core/seam.ts was called with `hasAgreement: true`
-- as a literal. The one precondition in the product that was asserted rather
-- than read, inside the function whose entire job is refusing to publish when
-- something is not true.
--
-- It is also the most consequential compliance moment in a residential
-- transaction, and the record of it is what an agent would be asked for.

alter table rift_leads add column if not exists representation text
  not null default 'none';

alter table rift_leads add column if not exists representation_signed_on date;
alter table rift_leads add column if not exists representation_expires_on date;

-- The vocabulary is closed, and it matches STATUSES in
-- lib/core/representation.ts exactly. A status outside this list does not
-- error anywhere: it simply fails `isCovered`, so the journey silently stops
-- advancing and nobody can see why.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_leads_representation_check') then
    alter table rift_leads add constraint rift_leads_representation_check
      check (representation in ('none','prepared','sent','signed','expired','declined'));
  end if;
end $$;

-- A signed agreement has a date it was signed.
--
-- Not "should have". The dates are the whole evidentiary value of the record:
-- "signed" with no date says an agreement exists without saying when it began,
-- which is the question that actually gets asked. Every other status has no
-- signing date by definition, and storing one against `declined` would be a
-- contradiction sitting in a column.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_leads_signed_is_dated') then
    alter table rift_leads add constraint rift_leads_signed_is_dated
      check (
        (representation = 'signed' and representation_signed_on is not null)
        or (representation <> 'signed' and representation_signed_on is null)
      );
  end if;
end $$;

-- An agreement cannot run out before it starts.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_leads_expiry_follows_signing') then
    alter table rift_leads add constraint rift_leads_expiry_follows_signing
      check (
        representation_expires_on is null
        or representation_signed_on is null
        or representation_expires_on >= representation_signed_on
      );
  end if;
end $$;

-- An expiry date belongs to an agreement. Recording one against a lead with
-- nothing signed is a date attached to nothing, and it would render on the
-- agent's screen as a deadline he has no way to meet.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_leads_expiry_needs_an_agreement') then
    alter table rift_leads add constraint rift_leads_expiry_needs_an_agreement
      check (representation_expires_on is null or representation_signed_on is not null);
  end if;
end $$;

comment on column rift_leads.representation is
  'none | prepared | sent | signed | expired | declined. Matches STATUSES in lib/core/representation.ts. NOTE: a stored ''signed'' with a past expiry reads as expired: standingOf() derives that rather than writing it back, because a derived truth stored twice is two truths.';

comment on column rift_leads.representation_expires_on is
  'Monitored deadline. docs/product.md: expiration "raises attention before it lapses, not after".';

create index if not exists rift_leads_representation_idx
  on rift_leads (agent_id, representation_expires_on)
  where representation = 'signed' and representation_expires_on is not null;


-- =====================================================================
-- 20260921050000_rift_decisions.sql
-- =====================================================================
-- Decision Rooms.
--
-- docs/benchmark.md scores criterion 4.3 at 0 in production. Not weak:
-- absent. The prototype has /app/decisions and a decision room; the shipped
-- product had no surface at all, and the criterion asks for rooms "at the
-- moments where clients actually stall, with scenarios and recorded outcomes".

create table if not exists rift_decisions (
  id          uuid primary key default gen_random_uuid(),
  agent_id    uuid not null references rift_agents(id) on delete cascade,
  lead_id     uuid not null references rift_leads(id) on delete cascade,

  kind        text not null default 'other'
              check (kind in ('affordability','offers','property','timing','other')),

  -- Written for the client to read, like a plan item. Bounded because it
  -- renders as a heading on their page and a paragraph in a heading slot is a
  -- paragraph nobody reads.
  question    text not null check (length(btrim(question)) between 5 and 200),

  -- The agent's framing. Optional, because a room with two clearly labelled
  -- options sometimes needs no preamble, and requiring one produces preamble.
  context     text check (context is null or length(btrim(context)) > 0),

  decide_by   date,

  -- Prepare-then-approve, criterion 2.2. NULL means the client cannot see it.
  -- Not a boolean: when it was released is the part that matters afterwards.
  released_at timestamptz,

  -- The recorded outcome. An outcome is a fact, not a state, which option,
  -- when, and in whose words.
  decided_at       timestamptz,
  chosen_option_id uuid,
  outcome_note     text,

  created_at  timestamptz not null default now()
);

create table if not exists rift_decision_options (
  id            uuid primary key default gen_random_uuid(),
  agent_id      uuid not null references rift_agents(id) on delete cascade,
  decision_id   uuid not null references rift_decisions(id) on delete cascade,

  label         text not null check (length(btrim(label)) between 1 and 120),
  detail        text,

  -- CENTS. These are money and a float is not money; the rest of this schema
  -- stores money the same way for the same reason.
  --
  -- NULL is meaningful and is not zero: "sell first, then buy" has no figure,
  -- and lib/core/decision.ts refuses to release a room where some options
  -- carry one and others do not, because side by side an option with no number
  -- reads as one that costs nothing.
  amount_cents  bigint,

  -- What that number IS: "would reach you", "a month", "at the table". Two
  -- options labelled differently are different quantities in the same column,
  -- and canRelease() refuses that too.
  amount_label  text,

  upside        text,
  downside      text,

  -- The agent's order. Never the amount: the largest number is not the best
  -- option, which is the entire point of headlineTrap in lib/core/offers.ts.
  sort          integer not null default 0,

  created_at    timestamptz not null default now()
);

-- A figure needs to say what it is. A bare number in a comparison column is
-- the reader's guess about what they are comparing.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_decision_options_amount_is_labelled') then
    alter table rift_decision_options add constraint rift_decision_options_amount_is_labelled
      check (amount_cents is null or length(btrim(coalesce(amount_label,''))) > 0);
  end if;
end $$;

-- The chosen option must belong to this decision.
--
-- A plain foreign key to rift_decision_options would let a decision be
-- recorded against an option from a DIFFERENT room, which renders as a
-- perfectly ordinary outcome naming an option the reader cannot see. The
-- composite key makes that unrepresentable.
create unique index if not exists rift_decision_options_scoped_idx
  on rift_decision_options (id, decision_id);

-- ON DELETE RESTRICT, and the alternative is worth recording because it was
-- written first and is a trap.
--
-- `on delete set null` here does NOT null only chosen_option_id. A composite
-- foreign key sets EVERY column in the key to null, and the second column of
-- this one is rift_decisions.id: the primary key. Deleting an option that a
-- decision named failed with "null value in column id violates not-null
-- constraint", which is the good outcome; the bad one was available on
-- Postgres 15+ as `set null (chosen_option_id)`, and writing version-specific
-- syntax into a migration applied by hand to a database whose version nobody
-- has checked is how a migration half-applies.
--
-- RESTRICT is also the better rule. An option a recorded decision names is
-- part of the record of what was decided, and quietly removable evidence is
-- not evidence. Reopen the decision first (which clears the reference) and
-- then the option can go.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_decisions_chosen_is_ours') then
    alter table rift_decisions add constraint rift_decisions_chosen_is_ours
      foreign key (chosen_option_id, id)
      references rift_decision_options (id, decision_id)
      on delete restrict
      deferrable initially deferred;
  end if;
end $$;

-- An outcome has a time and an option, or it has neither. Half an outcome is
-- a room that says a decision was made without saying what it was.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_decisions_outcome_is_whole') then
    alter table rift_decisions add constraint rift_decisions_outcome_is_whole
      check ((decided_at is null) = (chosen_option_id is null));
  end if;
end $$;

create index if not exists rift_decisions_lead_idx
  on rift_decisions (lead_id, created_at desc);

-- The client's own read: released rooms for one relationship.
create index if not exists rift_decisions_released_idx
  on rift_decisions (lead_id, released_at) where released_at is not null;

create index if not exists rift_decision_options_decision_idx
  on rift_decision_options (decision_id, sort);

alter table rift_decisions        enable row level security;
alter table rift_decision_options enable row level security;

drop policy if exists rift_decisions_owner on rift_decisions;
create policy rift_decisions_owner on rift_decisions
  for all using (agent_id = rift_my_agent_id()) with check (agent_id = rift_my_agent_id());

drop policy if exists rift_decision_options_owner on rift_decision_options;
create policy rift_decision_options_owner on rift_decision_options
  for all using (agent_id = rift_my_agent_id()) with check (agent_id = rift_my_agent_id());

comment on column rift_decisions.released_at is
  'NULL means the client cannot see this room. Prepare-then-approve, benchmark 2.2.';

comment on column rift_decision_options.amount_cents is
  'NULL is "this option has no figure", which is not zero. See canRelease() in lib/core/decision.ts.';


-- =====================================================================
-- 20260921060000_rift_inbound_offers.sql
-- =====================================================================
-- Rift Offer, inbound: the columns /offer writes and /studio/offers reads.
--
-- This migration was believed to exist and did not. `lib/db/offer-intake.ts`
-- shipped writing `property_address`, `submitted_email`, `submitted_phone`,
-- `submitted_firm`, `representing`, `source` and `submitter_lead_id` to a table
-- that has none of them, and reading them back in a nineteen-column select.
--
-- PostgREST answers an unknown column with an error about a schema cache, so
-- /studio/offers failed entirely and every /offer submission fell through to
-- its "we could not pass this on" fallback. The fallback is honest, which is
-- why this looked like an unconfigured feature rather than a broken one.
--
-- Found by scripts/verify-queries.mjs during a sweep of every column list in
-- lib/db, immediately after the same script found `rift_leads.figure_id`.

-- Where the offer came from. 'agent' is one Kaleb typed in against a listing
-- he holds; 'inbound' is one a stranger submitted at /offer.
alter table rift_offers add column if not exists source text not null default 'agent';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_offers_source_check') then
    alter table rift_offers add constraint rift_offers_source_check
      check (source in ('agent','inbound'));
  end if;
end $$;

-- The property. Required for an inbound offer and meaningless for an agent
-- one, where the offer already belongs to a seller whose address is known.
alter table rift_offers add column if not exists property_address text;

-- How to reach whoever sent it. A cooperating agent or an unrepresented buyer.
--
-- docs/privacy: the phone number given to deliver ONE offer is passed on with
-- it and never stored beyond the offer's own retention. These live on the
-- offer row rather than on a lead deliberately: the submitter is a third
-- party until they choose to become a relationship.
alter table rift_offers add column if not exists submitted_email text;
alter table rift_offers add column if not exists submitted_phone text;
alter table rift_offers add column if not exists submitted_firm  text;

-- Whose side they are on, in their own words. Never inferred.
alter table rift_offers add column if not exists representing text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_offers_representing_check') then
    alter table rift_offers add constraint rift_offers_representing_check
      check (representing is null or representing in ('buyer','self','other'));
  end if;
end $$;

-- If the submitter later becomes a relationship, this links the two.
--
-- SET NULL, not CASCADE. Deleting the lead must not delete the offer: the
-- record of what was received is the only protection either side has if the
-- terms are disputed, and vision.md is explicit that Rift never discards one.
alter table rift_offers add column if not exists submitter_lead_id uuid
  references rift_leads(id) on delete set null;

-- An inbound offer has no seller yet, because nobody has matched it to one.
alter table rift_offers alter column lead_id drop not null;

-- But it must be ABOUT something. A row with neither a seller nor an address
-- is an offer on nothing, and it would sit in the agent's queue forever with
-- no way to act on it.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_offers_has_a_subject') then
    alter table rift_offers add constraint rift_offers_has_a_subject
      check (lead_id is not null or length(btrim(coalesce(property_address,''))) > 0);
  end if;
end $$;

create index if not exists rift_offers_inbound_idx
  on rift_offers (agent_id, created_at desc) where source = 'inbound';

comment on column rift_offers.source is
  'agent | inbound. An inbound offer arrived at /offer from a stranger and has no seller attached until the agent matches it.';

comment on column rift_offers.submitted_phone is
  'Passed on with the offer, kept only for the offer''s own retention window. See RETENTION in lib/core/privacy.ts.';


-- =====================================================================
-- 20260921070000_rift_offer_room.sql
-- =====================================================================
-- ============================================================================
-- The offer room: the agent's take on a seller's offers, and the seller's
-- choice between them. Benchmark 2.2, prepare-then-approve.
--
-- One row per seller. Two halves, each written whole or not at all:
--
--   THE TAKE. `prepared` is Rift's draft exactly as it stood when the agent
--   approved; `take` is what he approved; `approved_for` is the set of released
--   offers it was written about. Stored together so the difference between
--   what the software drafted and what the agent said is a recorded fact
--   rather than a claim, which is what 2.2 asks for.
--
--   THE CHOICE. Which released offer the seller said they want, when, and a
--   snapshot of what they were shown (computed on the server, never sent by
--   the browser). Not an acceptance (the page says so) but a record that
--   survives the question "which one did they tell you they wanted?"
-- ============================================================================

-- The target of the composite key below. `id` is already unique; this pairs it
-- with its seller so a choice can only name an offer ON THIS SELLER.
create unique index if not exists rift_offers_id_lead_key on rift_offers (id, lead_id);

create table if not exists rift_offer_rooms (
  lead_id      uuid primary key references rift_leads(id) on delete cascade,
  agent_id     uuid not null references rift_agents(id) on delete cascade,

  prepared     text check (prepared is null or length(prepared) <= 4000),
  take         text check (take is null or length(btrim(take)) between 1 and 2000),
  approved_at  timestamptz,
  approved_for uuid[],

  chosen_offer_id uuid,
  chosen_at       timestamptz,
  chosen_seen     jsonb,
  client_note     text check (client_note is null or length(client_note) <= 1000),

  updated_at   timestamptz not null default now()
);

do $$
begin
  -- An approval is the take, the draft it came from, the moment and the offers
  -- it covers. Any one without the others is a take nobody can audit.
  if not exists (select 1 from pg_constraint where conname = 'rift_offer_rooms_approval_is_whole') then
    alter table rift_offer_rooms add constraint rift_offer_rooms_approval_is_whole
      check (
        (approved_at is null) = (take is null)
        and (approved_at is null) = (prepared is null)
        and (approved_at is null) = (approved_for is null)
      );
  end if;

  if not exists (select 1 from pg_constraint where conname = 'rift_offer_rooms_choice_is_whole') then
    alter table rift_offer_rooms add constraint rift_offer_rooms_choice_is_whole
      check (
        (chosen_offer_id is null) = (chosen_at is null)
        and (chosen_at is null) = (chosen_seen is null)
        and (client_note is null or chosen_offer_id is not null)
      );
  end if;

  -- COMPOSITE, and NO ACTION rather than SET NULL or RESTRICT.
  --
  -- Composite so the choice cannot name an offer on somebody else's house.
  -- Not SET NULL, because on a composite key that nulls every column in it:
  -- including lead_id, the primary key (the decisions migration learned that).
  -- Not RESTRICT, which is checked mid-cascade: forgetting a seller deletes
  -- both their offers and this row, and RESTRICT can fire between the two.
  -- NO ACTION is checked at the end of the statement, after the cascade.
  if not exists (select 1 from pg_constraint where conname = 'rift_offer_rooms_chosen_is_theirs') then
    alter table rift_offer_rooms add constraint rift_offer_rooms_chosen_is_theirs
      foreign key (chosen_offer_id, lead_id)
      references rift_offers (id, lead_id)
      on delete no action;
  end if;
end $$;

-- A seller can only choose what they can see.
create or replace function rift_offer_room_choice_is_released() returns trigger
language plpgsql as $$
begin
  if new.chosen_offer_id is not null
     and new.chosen_offer_id is distinct from coalesce(old.chosen_offer_id, '00000000-0000-0000-0000-000000000000'::uuid)
     and not exists (
       select 1 from rift_offers where id = new.chosen_offer_id and released_at is not null
     ) then
    raise exception 'offer % has not been released to the seller', new.chosen_offer_id
      using errcode = 'check_violation';
  end if;
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists rift_offer_room_choice_is_released on rift_offer_rooms;
create trigger rift_offer_room_choice_is_released
  before insert or update on rift_offer_rooms
  for each row execute function rift_offer_room_choice_is_released();

-- And an offer they chose cannot quietly vanish from their page. Withdrawing
-- it would leave a recorded choice pointing at something the seller can no
-- longer see; the agent reopens the choice first, on purpose.
create or replace function rift_offer_chosen_stays_released() returns trigger
language plpgsql as $$
begin
  if old.released_at is not null and new.released_at is null
     and exists (select 1 from rift_offer_rooms where chosen_offer_id = old.id) then
    raise exception 'the seller chose this offer; reopen their choice before withdrawing it'
      using errcode = 'check_violation';
  end if;
  return new;
end $$;

drop trigger if exists rift_offer_chosen_stays_released on rift_offers;
create trigger rift_offer_chosen_stays_released
  before update of released_at on rift_offers
  for each row execute function rift_offer_chosen_stays_released();

create index if not exists rift_offer_rooms_chosen_idx
  on rift_offer_rooms (agent_id, chosen_at desc) where chosen_offer_id is not null;

alter table rift_offer_rooms enable row level security;

drop policy if exists rift_offer_rooms_owner on rift_offer_rooms;
create policy rift_offer_rooms_owner on rift_offer_rooms
  for all using (agent_id = rift_my_agent_id()) with check (agent_id = rift_my_agent_id());

comment on table rift_offer_rooms is
  'The agent''s approved take on a seller''s released offers, and the seller''s recorded choice. Benchmark 2.2.';
comment on column rift_offer_rooms.prepared is
  'Rift''s draft as it stood at approval. Never shown to the client; kept so the edit is auditable.';
comment on column rift_offer_rooms.chosen_seen is
  'What the seller was shown when they chose, computed server-side. Not an acceptance.';


-- =====================================================================
-- 20260923000000_rift_plain_punctuation.sql
-- =====================================================================
-- ============================================================================
-- Stored copy follows the same punctuation rule as the code: no em dashes.
-- The old text is matched with U&'\2014', so this file does not contain the
-- sign either.
--
-- The code was rewritten on 23 September 2026. These are the rows that carried
-- the old wording into the database: copied from code when they were written
-- (lead score notes, the default question labels, programme conditions) or
-- written by the application as a reason (a delivery log line). Each update
-- names the exact old text, so a row that was edited by hand since is left
-- alone rather than rewritten by a guess.
--
-- Idempotent: once applied, no row matches any WHERE clause below.
-- ============================================================================

update rift_leads
   set signals = replace(signals::text,
         U&'No saving rate given \2014 timeline unknown',
         'No saving rate given, timeline unknown')::jsonb
 where signals::text like U&'%No saving rate given \2014 timeline unknown%';

update rift_leads
   set signals = replace(replace(replace(replace(replace(signals::text,
         U&'No contact details \2014 nothing can be done here', 'No contact details, nothing can be done here'),
         U&'Named \2014 bring them in early', 'Named: bring them in early'),
         U&'No way to reach them \2014 the assessment is all we have', 'No way to reach them; the assessment is all we have'),
         U&'Real, but the money is the constraint \2014 this is a nurture relationship, not a call',
         'Real, but the money is the constraint. This is a nurture relationship, not a call'),
         U&'Nothing to do \2014 waits for them to come back', 'Nothing to do. Waits for them to come back')::jsonb
 where signals::text like U&'%\2014%';

update rift_programs
   set conditions = array_replace(array_replace(conditions,
         U&'Forgiven over a residency period \2014 leaving early can trigger repayment',
         'Forgiven over a residency period; leaving early can trigger repayment'),
         U&'Matched savings requirement \2014 buyer funds are matched at a set ratio',
         'Matched savings requirement: buyer funds are matched at a set ratio')
 where array_to_string(conditions, '|') like U&'%\2014%';

update rift_programs
   set source_note = 'Lender guidance, general'
 where source_note = U&'Lender guidance \2014 general';

update rift_questions
   set options = replace(replace(options::text,
         U&'"Yes \2014 it was where I lived"', '"Yes, it was where I lived"'),
         U&'"Yes \2014 but it was a rental or investment property"', '"Yes, but it was a rental or investment property"')::jsonb
 where options::text like U&'%Yes \2014 %';

update rift_touches
   set detail = 'BREVO_FROM_EMAIL not set; Brevo rejects any send without a verified sender'
 where detail = U&'BREVO_FROM_EMAIL not set \2014 Brevo rejects any send without a verified sender';


-- =====================================================================
-- 20260923010000_rift_journeys.sql  (skipped when public.rift_journeys exists)
-- =====================================================================
do $guard$
begin
  if to_regclass('public.rift_journeys') is not null then
    raise notice '20260923010000_rift_journeys: already applied, skipped';
    return;
  end if;
  execute $m_20260923010000$
-- ============================================================================
-- Journey identity (blueprint v4, work package W01).
--
-- One buying or selling goal, linked to an existing relationship. Taken from
-- docs/blueprint-v4/first-migration-proposal.md with two changes: grants to
-- Supabase roles are conditional, so the same file runs against the local test
-- harness (which has no `authenticated` or `service_role`), and nothing else.
--
-- Identity only. No stage, no lifecycle, no client access. Members, search
-- revisions and the shortlist ship in the migrations after this one, each with
-- its own constraints and tests.
--
-- Deletion: `origin_lead_id` is RESTRICT. Once a journey exists, deleting its
-- lead is refused rather than silently cascading. The two code paths that
-- delete leads handle it explicitly: the retention sweep leaves leads with a
-- journey alone (they are being worked), and "delete all of it" removes the
-- journeys first. See lib/db/retention.ts.
-- ============================================================================

set local lock_timeout = '5s';
set local statement_timeout = '30s';

-- The composite key protects the parent link even when a service role bypasses RLS.
create unique index rift_leads_id_agent_for_journeys_uidx
  on public.rift_leads (id, agent_id);

create table public.rift_journeys (
  id              uuid primary key default gen_random_uuid(),
  agent_id        uuid not null references public.rift_agents(id)
                    on delete restrict,
  origin_lead_id  uuid not null,
  side            text not null check (side in ('buy', 'sell')),
  label           text not null
                    check (length(btrim(label)) between 1 and 160),
  created_at      timestamptz not null default now(),

  constraint rift_journeys_relationship_same_agent
    foreign key (origin_lead_id, agent_id)
    references public.rift_leads (id, agent_id)
    on delete restrict,

  constraint rift_journeys_id_agent_unique unique (id, agent_id)
);

-- The agent list and the relationship's journey list are the first two reads.
create index rift_journeys_agent_created_idx
  on public.rift_journeys (agent_id, created_at desc, id);
create index rift_journeys_origin_lead_idx
  on public.rift_journeys (origin_lead_id, created_at desc, id);

alter table public.rift_journeys enable row level security;

create policy rift_journeys_agent_select
  on public.rift_journeys
  for select to public
  using (agent_id = (select public.rift_my_agent_id()));

create policy rift_journeys_agent_insert
  on public.rift_journeys
  for insert to public
  with check (agent_id = (select public.rift_my_agent_id()));

create policy rift_journeys_agent_update
  on public.rift_journeys
  for update to public
  using (agent_id = (select public.rift_my_agent_id()))
  with check (agent_id = (select public.rift_my_agent_id()));

-- Explicit grants: RLS does not itself grant table access. Only the label is
-- editable through the authenticated role in this first seam. The policies
-- above name `public` so the same file runs where `authenticated` does not
-- exist; these grants are what narrow it to signed-in agents.
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on public.rift_journeys from anon;
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    revoke all on public.rift_journeys from authenticated;
    grant select on public.rift_journeys to authenticated;
    grant insert (agent_id, origin_lead_id, side, label) on public.rift_journeys to authenticated;
    grant update (label) on public.rift_journeys to authenticated;
  end if;
  -- Deletion remains behind the server's tenant-checked retention command.
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant select, insert, update, delete on public.rift_journeys to service_role;
  end if;
end $$;

comment on table public.rift_journeys is
  'One buying or selling goal linked to an existing Rift relationship. '
  'Identity only: lifecycle events, client membership and search revisions '
  'ship through separately reviewed migrations.';

comment on column public.rift_journeys.origin_lead_id is
  'Transitional relationship anchor. Deletion is explicit so retention '
  'cannot accidentally remove a future transaction file.';
$m_20260923010000$;
end
$guard$;


-- =====================================================================
-- 20260923020000_rift_journey_members.sql  (skipped when public.rift_journey_members exists)
-- =====================================================================
do $guard$
begin
  if to_regclass('public.rift_journey_members') is not null then
    raise notice '20260923020000_rift_journey_members: already applied, skipped';
    return;
  end if;
  execute $m_20260923020000$
-- ============================================================================
-- Who may take part in a journey (blueprint v4, W02; decision D03 confirmed:
-- email sign-in for private client pages).
--
-- A member row starts as an INVITATION: an address, a role, the scopes the
-- agent chose, and the SHA-256 of a one-time link. It becomes a MEMBERSHIP
-- when somebody signed in with that exact verified address opens the link.
-- Signing in never creates a membership on its own, and nothing here trusts
-- profile metadata a user can edit (REQ-ACCESS-01).
--
-- Revocation is a timestamp, not a delete: the record of who could see what,
-- and when, outlives the access itself. Every read and write on the client
-- side checks `revoked_at is null` at the moment it runs, so revoking takes
-- effect on the next request (AT05).
--
-- No client-side policy. Client pages read through the server, which checks
-- membership explicitly; direct table access stays agent-only until a
-- membership policy is designed and tested (first-migration-proposal §limits).
-- ============================================================================

set local lock_timeout = '5s';
set local statement_timeout = '30s';

create table public.rift_journey_members (
  id                 uuid primary key default gen_random_uuid(),
  agent_id           uuid not null references public.rift_agents(id) on delete restrict,
  journey_id         uuid not null,
  email              text not null
                       check (email = lower(btrim(email)) and length(email) between 3 and 254
                              and email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  display_name       text check (display_name is null or length(btrim(display_name)) between 1 and 120),
  role               text not null check (role in ('buyer', 'co-buyer', 'viewer')),
  scopes             text[] not null
                       check (cardinality(scopes) >= 1 and scopes <@ array['search', 'homes', 'money']::text[]),
  invite_token_hash  text unique check (invite_token_hash is null or invite_token_hash ~ '^[0-9a-f]{64}$'),
  invite_expires_at  timestamptz,
  auth_user_id       uuid references auth.users(id) on delete set null,
  invited_at         timestamptz not null default now(),
  accepted_at        timestamptz,
  revoked_at         timestamptz,

  constraint rift_journey_members_journey_same_agent
    foreign key (journey_id, agent_id)
    references public.rift_journeys (id, agent_id)
    on delete cascade,
  constraint rift_journey_members_id_journey unique (id, journey_id),

  -- A login is attached only by accepting. (A deleted login nulls the id and
  -- leaves the acceptance on record, which is the history, not access.)
  constraint rift_journey_members_user_means_accepted
    check (auth_user_id is null or accepted_at is not null),
  -- An invitation still waiting has a link and an expiry.
  constraint rift_journey_members_pending_has_link
    check (accepted_at is not null or revoked_at is not null
           or (invite_token_hash is not null and invite_expires_at is not null)),
  -- An accepted membership has no live link left to forward.
  constraint rift_journey_members_accepted_link_spent
    check (accepted_at is null or invite_token_hash is null)
);

-- One live row per address and per login on a journey. A second invitation to
-- the same address reissues the link on the existing row.
create unique index rift_journey_members_one_live_email
  on public.rift_journey_members (journey_id, email) where revoked_at is null;
create unique index rift_journey_members_one_live_user
  on public.rift_journey_members (journey_id, auth_user_id)
  where revoked_at is null and auth_user_id is not null;
-- "Which journeys can this signed-in person see": the client's first read.
create index rift_journey_members_user_idx
  on public.rift_journey_members (auth_user_id)
  where auth_user_id is not null and revoked_at is null;

alter table public.rift_journey_members enable row level security;

create policy rift_journey_members_agent
  on public.rift_journey_members
  for all to public
  using (agent_id = (select public.rift_my_agent_id()))
  with check (agent_id = (select public.rift_my_agent_id()));

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on public.rift_journey_members from anon;
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    revoke all on public.rift_journey_members from authenticated;
    grant select on public.rift_journey_members to authenticated;
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant select, insert, update, delete on public.rift_journey_members to service_role;
  end if;
end $$;

comment on table public.rift_journey_members is
  'Invitations and memberships for one journey. A row is an invitation until a '
  'person signed in with the same verified address accepts it. Revoked, never deleted.';
comment on column public.rift_journey_members.invite_token_hash is
  'SHA-256 of the one-time invitation link. The link itself is never stored.';
comment on column public.rift_journey_members.scopes is
  'search: the brief. homes: the shortlist. money: price and fee criteria.';
$m_20260923020000$;
end
$guard$;


-- =====================================================================
-- 20260923030000_rift_search.sql  (skipped when public.rift_search_revisions exists)
-- =====================================================================
do $guard$
begin
  if to_regclass('public.rift_search_revisions') is not null then
    raise notice '20260923030000_rift_search: already applied, skipped';
    return;
  end if;
  execute $m_20260923030000$
-- ============================================================================
-- The buyer's search brief and the Matrix search it becomes (blueprint v4,
-- W03 and W04; decision D10: buyer search is the first slice, and D04: the
-- agent approves every external action).
--
--   rift_search_revisions  The brief, versioned. A revision is never edited;
--                          a change is a new revision, numbered in order.
--   rift_search_responses  A household member confirming a revision, or
--                          asking for changes to it.
--   rift_search_packages   The agent's approval of one exact revision as a
--                          Matrix search, and then his record of setting it
--                          up there. Rift has no write access to Matrix, so
--                          "active" means the agent said so, with a reference.
--
-- Two functions carry the rules that must hold under concurrency and retries:
--   rift_approve_search_package   only the LATEST revision can be approved
--   rift_confirm_search_package   an approval whose revision has since been
--                                 superseded cannot be confirmed (AT12), and
--                                 the same request twice records once (AT13)
-- ============================================================================

set local lock_timeout = '5s';
set local statement_timeout = '30s';

-- ---------------------------------------------------------------------------
-- Revisions
-- ---------------------------------------------------------------------------

create table public.rift_search_revisions (
  id               uuid primary key default gen_random_uuid(),
  agent_id         uuid not null references public.rift_agents(id) on delete restrict,
  journey_id       uuid not null,
  revision         integer not null check (revision >= 1),
  schema_version   smallint not null check (schema_version >= 1),
  criteria         jsonb not null
                     check (jsonb_typeof(criteria) = 'array' and jsonb_array_length(criteria) <= 40),
  questions        jsonb not null default '[]'::jsonb
                     check (jsonb_typeof(questions) = 'array' and jsonb_array_length(questions) <= 10),
  note             text check (note is null or length(note) <= 2000),
  author_kind      text not null check (author_kind in ('agent', 'client')),
  -- Deliberately not a foreign key. A revision is a record of what somebody
  -- said; a later change to their membership must never rewrite it.
  author_member_id uuid,
  author_label     text not null check (length(btrim(author_label)) between 1 and 120),
  created_at       timestamptz not null default now(),

  constraint rift_search_revisions_journey_same_agent
    foreign key (journey_id, agent_id)
    references public.rift_journeys (id, agent_id)
    on delete cascade,
  constraint rift_search_revisions_one_number unique (journey_id, revision),
  constraint rift_search_revisions_id_journey unique (id, journey_id),
  constraint rift_search_revisions_author
    check ((author_kind = 'agent') = (author_member_id is null))
);

create or replace function public.rift_search_revision_rules() returns trigger
language plpgsql as $$
declare latest integer;
begin
  if tg_op = 'UPDATE' then
    raise exception 'search revision % is a record and cannot be edited; save a new revision', old.revision
      using errcode = 'check_violation';
  end if;
  -- In order, no gaps: revision N+1 is only ever written on top of N.
  select coalesce(max(revision), 0) into latest
    from public.rift_search_revisions where journey_id = new.journey_id;
  if new.revision <> latest + 1 then
    raise exception 'revision % is out of order; the latest is %', new.revision, latest
      using errcode = 'serialization_failure';
  end if;
  return new;
end $$;

create trigger rift_search_revision_rules
  before insert or update on public.rift_search_revisions
  for each row execute function public.rift_search_revision_rules();

-- ---------------------------------------------------------------------------
-- Household responses
-- ---------------------------------------------------------------------------

create table public.rift_search_responses (
  id           uuid primary key default gen_random_uuid(),
  agent_id     uuid not null references public.rift_agents(id) on delete restrict,
  journey_id   uuid not null,
  revision_id  uuid not null,
  member_id    uuid not null,
  response     text not null check (response in ('confirmed', 'changes-requested')),
  note         text check (note is null or length(btrim(note)) between 1 and 1000),
  created_at   timestamptz not null default now(),

  constraint rift_search_responses_journey_same_agent
    foreign key (journey_id, agent_id) references public.rift_journeys (id, agent_id) on delete cascade,
  constraint rift_search_responses_revision_on_journey
    foreign key (revision_id, journey_id) references public.rift_search_revisions (id, journey_id) on delete cascade,
  constraint rift_search_responses_member_on_journey
    foreign key (member_id, journey_id) references public.rift_journey_members (id, journey_id) on delete cascade,
  constraint rift_search_responses_changes_say_why
    check (response = 'confirmed' or note is not null)
);
create index rift_search_responses_revision_idx on public.rift_search_responses (revision_id, created_at);

-- ---------------------------------------------------------------------------
-- Packages: approval, then the agent's record of setting it up
-- ---------------------------------------------------------------------------

create table public.rift_search_packages (
  id                 uuid primary key default gen_random_uuid(),
  agent_id           uuid not null references public.rift_agents(id) on delete restrict,
  journey_id         uuid not null,
  revision_id        uuid not null,
  destination        text not null check (destination = 'matrix'),
  cadence            text not null check (cadence in ('instant', 'daily', 'weekly')),
  package            jsonb not null check (jsonb_typeof(package) = 'object'),
  package_hash       text not null check (package_hash ~ '^[0-9a-f]{64}$'),
  approved_at        timestamptz not null default now(),
  approved_by        text not null check (length(btrim(approved_by)) between 1 and 120),
  request_id         uuid not null unique,
  status             text not null default 'manual-action-needed'
                       check (status in ('manual-action-needed', 'active-confirmed', 'paused', 'superseded', 'cancelled')),
  external_ref       text check (external_ref is null or length(btrim(external_ref)) between 1 and 200),
  external_url       text check (external_url is null or (external_url ~ '^https?://' and length(external_url) <= 500)),
  confirmed_at       timestamptz,
  confirm_note       text check (confirm_note is null or length(confirm_note) <= 1000),
  confirm_request_id uuid unique,
  ended_at           timestamptz,
  ended_reason       text check (ended_reason is null or length(ended_reason) <= 300),

  constraint rift_search_packages_journey_same_agent
    foreign key (journey_id, agent_id) references public.rift_journeys (id, agent_id) on delete cascade,
  constraint rift_search_packages_revision_on_journey
    foreign key (revision_id, journey_id) references public.rift_search_revisions (id, journey_id) on delete cascade,
  -- Active or paused means the agent recorded it, with something to find it by.
  constraint rift_search_packages_confirmed_has_evidence
    check (status not in ('active-confirmed', 'paused')
           or (confirmed_at is not null and (external_ref is not null or external_url is not null))),
  constraint rift_search_packages_ended_is_whole
    check ((status in ('superseded', 'cancelled')) = (ended_at is not null))
);

-- One approval waiting, and one search in Matrix, per journey and destination.
create unique index rift_search_packages_one_waiting
  on public.rift_search_packages (journey_id, destination) where status = 'manual-action-needed';
create unique index rift_search_packages_one_live
  on public.rift_search_packages (journey_id, destination) where status in ('active-confirmed', 'paused');
create index rift_search_packages_agent_idx
  on public.rift_search_packages (agent_id, status);

-- What was approved is fixed. Only the lifecycle columns move.
create or replace function public.rift_search_package_is_fixed() returns trigger
language plpgsql as $$
begin
  if new.package is distinct from old.package or new.package_hash is distinct from old.package_hash
     or new.revision_id is distinct from old.revision_id or new.cadence is distinct from old.cadence
     or new.destination is distinct from old.destination or new.approved_at is distinct from old.approved_at
     or new.approved_by is distinct from old.approved_by or new.request_id is distinct from old.request_id
     or new.journey_id is distinct from old.journey_id or new.agent_id is distinct from old.agent_id then
    raise exception 'an approved search package cannot be changed; approve a new one'
      using errcode = 'check_violation';
  end if;
  return new;
end $$;

create trigger rift_search_package_is_fixed
  before update on public.rift_search_packages
  for each row execute function public.rift_search_package_is_fixed();

-- ---------------------------------------------------------------------------
-- Commands
-- ---------------------------------------------------------------------------

create or replace function public.rift_approve_search_package(
  p_agent uuid, p_journey uuid, p_revision uuid, p_cadence text,
  p_package jsonb, p_hash text, p_by text, p_request uuid
) returns uuid
language plpgsql as $$
declare
  existing uuid;
  latest uuid;
  made uuid;
begin
  -- The same request twice is one approval.
  select id into existing from public.rift_search_packages where request_id = p_request;
  if existing is not null then return existing; end if;

  perform 1 from public.rift_journeys where id = p_journey and agent_id = p_agent for update;
  if not found then
    raise exception 'that journey is not in your book' using errcode = 'insufficient_privilege';
  end if;

  select id into latest from public.rift_search_revisions
   where journey_id = p_journey order by revision desc limit 1;
  if latest is distinct from p_revision then
    raise exception 'the brief changed while you were reviewing it; review the latest revision'
      using errcode = 'serialization_failure';
  end if;

  update public.rift_search_packages
     set status = 'cancelled', ended_at = now(), ended_reason = 'replaced by a newer approval'
   where journey_id = p_journey and destination = 'matrix' and status = 'manual-action-needed';

  insert into public.rift_search_packages
    (agent_id, journey_id, revision_id, destination, cadence, package, package_hash, approved_by, request_id)
  values
    (p_agent, p_journey, p_revision, 'matrix', p_cadence, p_package, p_hash, p_by, p_request)
  returning id into made;
  return made;
end $$;

create or replace function public.rift_confirm_search_package(
  p_agent uuid, p_package uuid, p_ref text, p_url text, p_note text, p_request uuid
) returns uuid
language plpgsql as $$
declare
  existing uuid;
  pkg record;
  latest uuid;
begin
  select id into existing from public.rift_search_packages where confirm_request_id = p_request;
  if existing is not null then return existing; end if;

  select * into pkg from public.rift_search_packages
   where id = p_package and agent_id = p_agent for update;
  if not found then
    raise exception 'that search is not in your book' using errcode = 'insufficient_privilege';
  end if;
  if pkg.status <> 'manual-action-needed' then
    raise exception 'this approval is %, so there is nothing to record against it', pkg.status
      using errcode = 'check_violation';
  end if;

  select id into latest from public.rift_search_revisions
   where journey_id = pkg.journey_id order by revision desc limit 1;
  if latest is distinct from pkg.revision_id then
    raise exception 'the brief changed after you approved this search; review and approve the latest revision first'
      using errcode = 'serialization_failure';
  end if;

  update public.rift_search_packages
     set status = 'superseded', ended_at = now(), ended_reason = 'replaced by a newer search'
   where journey_id = pkg.journey_id and destination = pkg.destination
     and status in ('active-confirmed', 'paused');

  update public.rift_search_packages
     set status = 'active-confirmed',
         external_ref = nullif(btrim(p_ref), ''),
         external_url = nullif(btrim(p_url), ''),
         confirm_note = nullif(btrim(p_note), ''),
         confirmed_at = now(),
         confirm_request_id = p_request
   where id = p_package;
  return p_package;
end $$;

-- ---------------------------------------------------------------------------
-- Access
-- ---------------------------------------------------------------------------

alter table public.rift_search_revisions enable row level security;
alter table public.rift_search_responses enable row level security;
alter table public.rift_search_packages  enable row level security;

create policy rift_search_revisions_agent on public.rift_search_revisions
  for all to public
  using (agent_id = (select public.rift_my_agent_id()))
  with check (agent_id = (select public.rift_my_agent_id()));
create policy rift_search_responses_agent on public.rift_search_responses
  for all to public
  using (agent_id = (select public.rift_my_agent_id()))
  with check (agent_id = (select public.rift_my_agent_id()));
create policy rift_search_packages_agent on public.rift_search_packages
  for all to public
  using (agent_id = (select public.rift_my_agent_id()))
  with check (agent_id = (select public.rift_my_agent_id()));

-- The commands take an agent id as an argument, so nobody but the server may
-- call them: a signed-in user passing somebody else's id must get nothing.
revoke all on function public.rift_approve_search_package(uuid, uuid, uuid, text, jsonb, text, text, uuid) from public;
revoke all on function public.rift_confirm_search_package(uuid, uuid, text, text, text, uuid) from public;

do $$
declare t text;
begin
  foreach t in array array['rift_search_revisions', 'rift_search_responses', 'rift_search_packages'] loop
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on public.%I from anon', t);
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
      execute format('revoke all on public.%I from authenticated', t);
      execute format('grant select on public.%I to authenticated', t);
    end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then
      execute format('grant select, insert, update, delete on public.%I to service_role', t);
    end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.rift_approve_search_package(uuid, uuid, uuid, text, jsonb, text, text, uuid) to service_role;
    grant execute on function public.rift_confirm_search_package(uuid, uuid, text, text, text, uuid) to service_role;
  end if;
end $$;

comment on table public.rift_search_revisions is
  'A buyer''s search brief, one row per version. Never edited; see lib/core/search.ts for the criterion contract.';
comment on table public.rift_search_packages is
  'An approved revision as a Matrix search. active-confirmed means the AGENT recorded setting it up; Rift has no write access to Matrix.';
$m_20260923030000$;
end
$guard$;


