-- =====================================================================
-- 20260925010000_rift_reconciliations.sql  (skipped when public.rift_reconciliations exists)
-- =====================================================================
do $guard$
begin
  if to_regclass('public.rift_reconciliations') is not null then
    raise notice '20260925010000_rift_reconciliations: already applied, skipped';
    return;
  end if;
  execute $m_20260925010000$
-- ============================================================================
-- Pilot reconciliation (blueprint v4 W12; implementation plan §8 step 4).
--
-- Rift cannot see Matrix or the signed documents. What it holds is the
-- agent's record of them: the search he set up, the dates he entered. During
-- the pilot he checks, buyer by buyer, that the record still matches the
-- source, and this is where each check is kept:
--
--   search   the live Matrix search against the approved package it came
--            from: 'matches', 'differs', or 'none' when there is no live
--            search to check (then no package is named).
--   dates    the open contract's dates against the documents, the same way.
--   note     required when either differs: what differed and what was done.
--
-- Each check is history. A difference is resolved by fixing the source or
-- the record and checking again, never by editing the old check. The pilot
-- report reads the latest check per journey and says when the search or the
-- dates changed after it (lib/core/pilot.ts).
--
-- Additive: one new table, and a (id, journey_id) key on the packages so a
-- check can only name a package on its own journey.
-- ============================================================================

set local lock_timeout = '5s';
set local statement_timeout = '30s';

alter table public.rift_search_packages
  add constraint rift_search_packages_id_journey unique (id, journey_id);

create table public.rift_reconciliations (
  id                 uuid primary key default gen_random_uuid(),
  agent_id           uuid not null references public.rift_agents(id) on delete restrict,
  journey_id         uuid not null,
  search_package_id  uuid,
  search             text not null check (search in ('matches', 'differs', 'none')),
  dates              text not null check (dates in ('matches', 'differs', 'none')),
  note               text check (note is null or length(btrim(note)) between 3 and 1000),
  actor_label        text not null check (length(btrim(actor_label)) between 1 and 120),
  request_id         uuid not null unique,
  created_at         timestamptz not null default now(),

  constraint rift_reconciliations_journey_same_agent
    foreign key (journey_id, agent_id) references public.rift_journeys (id, agent_id) on delete cascade,
  constraint rift_reconciliations_package_on_journey
    foreign key (search_package_id, journey_id) references public.rift_search_packages (id, journey_id) on delete cascade,
  -- A checked search names the package it was checked against; no search names none.
  constraint rift_reconciliations_search_names_package check ((search = 'none') = (search_package_id is null)),
  -- A difference says what it was.
  constraint rift_reconciliations_difference_says_what check ((search <> 'differs' and dates <> 'differs') or note is not null),
  -- A check that checked nothing is not a check.
  constraint rift_reconciliations_checked_something check (search <> 'none' or dates <> 'none')
);
create index rift_reconciliations_journey_idx on public.rift_reconciliations (journey_id, created_at desc);
create index rift_reconciliations_agent_idx on public.rift_reconciliations (agent_id, created_at desc);

create or replace function public.rift_reconciliations_are_history() returns trigger
language plpgsql as $$
begin
  raise exception '% is history and cannot be edited; record a new check', tg_table_name
    using errcode = 'check_violation';
end $$;

create trigger rift_reconciliations_are_history before update on public.rift_reconciliations
  for each row execute function public.rift_reconciliations_are_history();

alter table public.rift_reconciliations enable row level security;
create policy rift_reconciliations_agent on public.rift_reconciliations for all to public
  using (agent_id = (select public.rift_my_agent_id())) with check (agent_id = (select public.rift_my_agent_id()));

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on public.rift_reconciliations from anon;
    revoke execute on function public.rift_reconciliations_are_history() from anon;
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    revoke all on public.rift_reconciliations from authenticated;
    grant select on public.rift_reconciliations to authenticated;
    revoke execute on function public.rift_reconciliations_are_history() from authenticated;
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant select, insert, delete on public.rift_reconciliations to service_role;
  end if;
end $$;

comment on table public.rift_reconciliations is
  'Each pilot check that Rift''s record of a buyer''s Matrix search and contract dates still matches the source. History; the latest is current.';
$m_20260925010000$;
end
$guard$;


-- =====================================================================
-- 20260926000000_rift_events_allowlist_values.sql
-- =====================================================================
-- Blueprint v5 §5.1: the lead side is now separate values (small tools), and
-- completion is measured per value without recording answers. One key is
-- added to the telemetry allowlist: `tool`, the id of the value (for example
-- "cash" or "assistance"). It names which tool, never what was answered. Not
-- `value`: that key is the one an answer would travel under, and the schema
-- test proves it is refused.
--
-- The application list is ALLOWED_META in lib/core/telemetry.ts; the two are
-- held equal by lib/core/telemetry.test.ts.

alter table rift_events drop constraint if exists events_carry_no_answer;

alter table rift_events add constraint events_carry_no_answer check (
  payload - array[
    'page','qid','step','of','from','via',
    'answered','matched','source','band','prefilled','live',
    'hasTopic','delivered','consent','slot','tool'
  ] = '{}'::jsonb
);


-- =====================================================================
-- 20260926010000_rift_saved_plan.sql
-- =====================================================================
-- Blueprint v5 §5.5: "Save my plan". A person who has used the values keeps
-- them together as a plan they can reopen on any device, by a private link.
--
-- Stored on the lead the save creates, because that is what it is: the
-- values they found, with the figures as they were shown and the day, and the
-- answers behind them. It is deleted with the lead ("delete all of it"), and
-- it is what the agent's lead summary and a later client brief read (§5.5,
-- LEAD-04). The link token is the credential, like a shared readout's, and is
-- never shown in Operations.
--
-- Additive only. Nothing reads these columns until the code that writes them
-- is deployed, and the capture path does not depend on them.

alter table rift_leads add column if not exists plan jsonb;
alter table rift_leads add column if not exists plan_token text;
alter table rift_leads add column if not exists plan_saved_at timestamptz;

create unique index if not exists rift_leads_plan_token_key on rift_leads (plan_token) where plan_token is not null;

alter table rift_leads drop constraint if exists plan_is_an_object;
alter table rift_leads add constraint plan_is_an_object check (plan is null or jsonb_typeof(plan) = 'object');
alter table rift_leads drop constraint if exists plan_token_is_long;
alter table rift_leads add constraint plan_token_is_long check (plan_token is null or length(plan_token) >= 32);


-- =====================================================================
-- 20260927000000_rift_offer_terms.sql
-- =====================================================================
-- Submit an offer, Blueprint v5 §5.9 (Kaleb, R2).
--
-- Two terms the public form now asks for. Both are nullable: every offer
-- received before today has neither, and an offer on file is never rewritten
-- to look as if it said something it did not.
--
-- No new table, so no new policy: rift_offers keeps the row-level security
-- it shipped with in 20260921060000_rift_inbound_offers.sql.

-- What "Other" financing actually is. The form refuses "Other" without it.
alter table rift_offers add column if not exists financing_detail text;

-- Days of due diligence asked for. Null means the sender did not say, which
-- is different from zero, a real and aggressive term.
alter table rift_offers add column if not exists due_diligence_days integer;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rift_offers_financing_detail_check') then
    alter table rift_offers add constraint rift_offers_financing_detail_check
      check (financing_detail is null or char_length(financing_detail) between 2 and 120);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'rift_offers_due_diligence_days_check') then
    alter table rift_offers add constraint rift_offers_due_diligence_days_check
      check (due_diligence_days is null or due_diligence_days between 0 and 60);
  end if;
end $$;


-- =====================================================================
-- 20260927010000_rift_ai_usage.sql
-- =====================================================================
-- AI cost controls, AUTO-06 and decision D16 (Blueprint v5 §10.2).
--
-- One row per AI call, written BEFORE the call as a reservation at its worst
-- case and settled afterwards at what it actually cost. The monthly limit is
-- the sum of this table for the month, reservations included, so two calls
-- racing each other cannot both spend the last of the money. Running out
-- means the page offers manual entry; nothing is ever lost because the budget
-- is spent (AT38).
--
-- Model and prompt version are recorded on every row so any output can be
-- traced to what produced it. No document content, no extracted values and no
-- personal data are stored here: only what the call cost.

create table if not exists public.rift_ai_usage (
  id              uuid primary key default gen_random_uuid(),
  agent_id        uuid not null references public.rift_agents(id) on delete restrict,
  workflow        text not null check (workflow ~ '^[a-z][a-z0-9-]{1,40}$'),
  model           text not null check (length(model) between 3 and 80),
  prompt_version  text not null check (length(prompt_version) between 1 and 40),
  status          text not null check (status in ('reserved', 'spent', 'failed')),
  -- US cents, fractional: a small call costs well under one cent.
  reserved_cents  numeric(12, 4) not null check (reserved_cents >= 0),
  cost_cents      numeric(12, 4) check (cost_cents is null or cost_cents >= 0),
  input_tokens    integer check (input_tokens is null or input_tokens >= 0),
  output_tokens   integer check (output_tokens is null or output_tokens >= 0),
  created_at      timestamptz not null default now(),
  settled_at      timestamptz
);

create index if not exists rift_ai_usage_month_idx on public.rift_ai_usage (agent_id, created_at);

alter table public.rift_ai_usage enable row level security;

-- The agent can see what AI has cost; only the server writes (service role).
drop policy if exists rift_ai_usage_agent_read on public.rift_ai_usage;
create policy rift_ai_usage_agent_read on public.rift_ai_usage
  for select to public
  using (agent_id = (select public.rift_my_agent_id()));


-- =====================================================================
-- 20260927020000_rift_document_shares.sql
-- =====================================================================
-- Documents shared with the household (Blueprint v5 §7.2: "every document
-- shared with them in one place, not only through offers").
--
-- History, never edited: each row is one decision by the agent about one
-- document, and the latest row for a document is the one that holds.
-- 'household' is everyone on the journey; 'money' is only members who were
-- given the money scope, the same line the offers already draw; 'none'
-- withdraws a share. Withdrawing stops new links being minted; it cannot
-- recall a copy somebody already saved, and the agent's screen says so.
--
-- Cascades with the document, and the document with its journey, so "delete
-- all of it" removes these with everything else.

begin;

set local lock_timeout = '5s';
set local statement_timeout = '30s';

create table if not exists public.rift_document_shares (
  id           uuid primary key default gen_random_uuid(),
  agent_id     uuid not null references public.rift_agents(id) on delete restrict,
  journey_id   uuid not null,
  document_id  uuid not null,
  audience     text not null check (audience in ('household', 'money', 'none')),
  actor_label  text not null check (length(btrim(actor_label)) between 1 and 120),
  created_at   timestamptz not null default now(),
  constraint rift_document_shares_document
    foreign key (document_id, journey_id) references public.rift_documents (id, journey_id) on delete cascade
);
create index if not exists rift_document_shares_journey_idx on public.rift_document_shares (journey_id, created_at);

create or replace function public.rift_document_share_is_history() returns trigger
language plpgsql as $$
begin
  raise exception 'a share decision is history and cannot be edited; record a new one'
    using errcode = 'check_violation';
end $$;

drop trigger if exists rift_document_share_is_history on public.rift_document_shares;
create trigger rift_document_share_is_history
  before update on public.rift_document_shares
  for each row execute function public.rift_document_share_is_history();

alter table public.rift_document_shares enable row level security;

drop policy if exists rift_document_shares_agent on public.rift_document_shares;
create policy rift_document_shares_agent on public.rift_document_shares
  for all to public
  using (agent_id = (select public.rift_my_agent_id()))
  with check (agent_id = (select public.rift_my_agent_id()));

commit;


-- =====================================================================
-- 20260927030000_rift_summary_links.sql
-- =====================================================================
-- Read-only summary links (ACCESS-02, Blueprint v5 §7.2): a household member
-- sends a parent, a lender or a friend a view of chosen parts of the move,
-- without inviting them into the household.
--
-- The link's token is never stored: only its SHA-256, so a copy of this
-- table opens nothing. Each link names its parts explicitly, expires, and can
-- be revoked; a revoked or expired link opens nothing and says so. No money
-- figures are ever in a summary in this first version.

begin;

set local lock_timeout = '5s';
set local statement_timeout = '30s';

create table if not exists public.rift_summary_links (
  id              uuid primary key default gen_random_uuid(),
  agent_id        uuid not null references public.rift_agents(id) on delete restrict,
  journey_id      uuid not null,
  created_by      uuid not null,
  token_hash      text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  parts           text[] not null check (
    cardinality(parts) between 1 and 3 and parts <@ array['stage', 'dates', 'homes']::text[]
  ),
  -- Who it is for, in the member's words, so they can tell their links apart.
  label           text not null check (length(btrim(label)) between 1 and 80),
  expires_at      timestamptz not null,
  revoked_at      timestamptz,
  created_at      timestamptz not null default now(),
  -- The creator must be a member of this same journey.
  constraint rift_summary_links_member_same_journey
    foreign key (created_by, journey_id) references public.rift_journey_members (id, journey_id) on delete cascade,
  constraint rift_summary_links_journey_same_agent
    foreign key (journey_id, agent_id) references public.rift_journeys (id, agent_id) on delete cascade,
  constraint rift_summary_links_expiry check (expires_at > created_at and expires_at <= created_at + interval '91 days')
);
create index if not exists rift_summary_links_member_idx on public.rift_summary_links (created_by, created_at desc);

alter table public.rift_summary_links enable row level security;

drop policy if exists rift_summary_links_agent on public.rift_summary_links;
create policy rift_summary_links_agent on public.rift_summary_links
  for all to public
  using (agent_id = (select public.rift_my_agent_id()))
  with check (agent_id = (select public.rift_my_agent_id()));

commit;


-- =====================================================================
-- 20260928000000_rift_step_marks.sql  (skipped when public.rift_step_marks exists)
-- =====================================================================
do $guard$
begin
  if to_regclass('public.rift_step_marks') is not null then
    raise notice '20260928000000_rift_step_marks: already applied, skipped';
    return;
  end if;
  execute $m_20260928000000$
-- ============================================================================
-- The journey checklist (Blueprint v5 §8.6; lib/core/checklist.ts).
--
-- Each stage of a journey is a checklist of steps from the journey contracts,
-- each naming who does it. The steps themselves are code; what the agent
-- records against them is here, as history:
--
--   rift_step_marks   one row per thing recorded against one step of one
--                     journey: done (who did or confirmed it, and the day),
--                     reported (someone says so; nobody who can confirm it
--                     has), not needed (and why), or reopened (and why).
--                     The latest row for a step is where it stands.
--
-- The ten workstreams under contract are steps too, but their state lives in
-- rift_workstream_updates and is changed there; nothing here duplicates it.
--
-- Rule 9 is held by the checks below as well as by the writer: nothing is
-- done without a named party and a day, and a reopening says why. Only the
-- agent records marks; a client's word, when there is a way for them to give
-- it, arrives as 'reported'.
--
-- Retention: cascades when the journey is erased, like everything on it.
-- ============================================================================

set local lock_timeout = '5s';
set local statement_timeout = '30s';

create table public.rift_step_marks (
  id           uuid primary key default gen_random_uuid(),
  agent_id     uuid not null references public.rift_agents(id) on delete restrict,
  journey_id   uuid not null,
  -- A step id from lib/core/checklist.ts: b- for buying, s- for selling.
  step_id      text not null check (step_id ~ '^[bs]-[a-z0-9-]{1,40}$'),
  -- One sequence per step: two people recording at once, one is told to reload.
  seq          integer not null check (seq >= 1),
  state        text not null check (state in ('done', 'reported', 'not-needed', 'reopened')),
  -- Who did it, confirmed it, or says it happened.
  by_name      text check (by_name is null or length(btrim(by_name)) between 1 and 160),
  -- The day it happened, which may be before the day it was recorded.
  done_on      date,
  note         text check (note is null or length(btrim(note)) between 1 and 500),
  actor_label  text not null check (length(btrim(actor_label)) between 1 and 120),
  request_id   uuid not null unique,
  created_at   timestamptz not null default now(),

  constraint rift_step_marks_journey_same_agent
    foreign key (journey_id, agent_id) references public.rift_journeys (id, agent_id) on delete cascade,
  constraint rift_step_marks_seq unique (journey_id, step_id, seq),
  -- Rule 9: done names who and the day.
  constraint rift_step_marks_done_is_named check (state <> 'done' or (by_name is not null and done_on is not null)),
  -- UX-02: a report says whose word it is.
  constraint rift_step_marks_report_is_named check (state <> 'reported' or by_name is not null),
  constraint rift_step_marks_skip_says_why check (state not in ('not-needed', 'reopened') or note is not null)
);
create index rift_step_marks_journey_idx on public.rift_step_marks (journey_id, step_id, seq);

-- History is never edited. UPDATE only: a delete must still cascade when a
-- journey is erased (handoff 9b). The function is the progress tables' own.
create trigger rift_step_marks_are_history before update on public.rift_step_marks
  for each row execute function public.rift_progress_is_history();

alter table public.rift_step_marks enable row level security;
create policy rift_step_marks_agent on public.rift_step_marks for all to public
  using (agent_id = (select public.rift_my_agent_id()))
  with check (agent_id = (select public.rift_my_agent_id()));

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on public.rift_step_marks from anon;
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    revoke all on public.rift_step_marks from authenticated;
    grant select on public.rift_step_marks to authenticated;
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant select, insert, update, delete on public.rift_step_marks to service_role;
  end if;
end $$;

comment on table public.rift_step_marks is
  'What the agent recorded against one checklist step of one journey. The latest row per step is where it stands; done needs who and the day.';
$m_20260928000000$;
end
$guard$;

-- PostgREST reloads its schema cache within a minute. Until it does, the
-- first write to a new column can fail with a message about a schema cache.
notify pgrst, 'reload schema';
